          .map(() =>
            request(app.getHttpServer() as Express.Application)
              .get('/api/user/profile')
              .set('Authorization', `Bearer ${token}`),
          ),

        // Attack requests - invalid tokens (15)
        ...Array(15)
          .fill(null)
          .map(() =>
            request(app.getHttpServer() as Express.Application)
              .get('/api/admin/users')
              .set('Authorization', 'Bearer invalid-token'),
