          event.message.includes('security') ||
          event.message.includes('auth') ||
          event.message.includes('attack') ||
          event.message.includes('unauthorized'),
      );

      expect(securityAuditEvents.length).toBeGreaterThan(0);

      // Verify audit events contain critical information
      const hasIPTracking = auditEvents.some(
        (event) =>
          event.message.includes('192.168.100.100') ||
          event.message.includes('10.0.100.100'),
      );

      expect(hasIPTracking).toBe(true);

      pentestLogger.critical(
        `[${testId}] Security audit trail generated: ${securityAuditEvents.length} security events logged`,
      );
    });
  });
});

/**
 * JWT Authentication Guard - ByteBotd Computer Control Service
 * Protects computer automation endpoints with JWT token validation
 *
 * Features:
 * - JWT token validation with automatic user extraction
 * - Comprehensive security logging for computer control access
 * - Request context enhancement with authenticated user
 * - Graceful error handling for authentication failures
 * - Integration with shared security types
 *
 * @author Security Implementation Specialist
 * @version 1.0.0
 * @since ByteBotd Authentication Hardening
 */

import {
  Injectable,
  ExecutionContext,
  UnauthorizedException,
  Logger,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Reflector } from '@nestjs/core';
import { Request } from 'express';
import { UserRole } from '@bytebot/shared';

/**
 * User interface for ByteBotd (subset of full User model)
 */
export interface ByteBotdUser {
  id: string;
  email: string;
  username: string;
  firstName?: string;
  lastName?: string;
  role: UserRole;
  isActive: boolean;
}

/**
 * Extended Request interface with authenticated user
 */
export interface AuthenticatedRequest extends Request {
  user: ByteBotdUser;
}

/**
 * JWT authentication error types for error handling
 */
interface JwtAuthError extends Error {
  message: string;
  name: string;
}

/**
 * JWT authentication info object containing validation details
 */
interface JwtAuthInfo {
  message?: string;
  name?: string;
  [key: string]: unknown;
}

/**
 * Standard JWT payload interface with standard claims
 */
interface StandardJwtPayload {
  /** Subject (usually user ID) */
  sub?: string;
  /** Issued at time (Unix timestamp) */
  iat?: number;
  /** Expiration time (Unix timestamp) */
  exp?: number;
  /** Not before time (Unix timestamp) */
  nbf?: number;
  /** JWT ID */
  jti?: string;
  /** Issuer */
  iss?: string;
  /** Audience */
  aud?: string | string[];
  [key: string]: unknown;
}

/**
 * JWT Authentication Guard for ByteBotd
 * Validates JWT tokens and protects computer control routes
 */
@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  private readonly logger = new Logger(JwtAuthGuard.name);

  constructor(private readonly reflector: Reflector) {
    super();
  }

  /**
   * Enhanced JWT validation with comprehensive security checks
   * Validates JWT token, extracts authenticated user, and performs additional security validations
   *
   * @param context - Execution context containing request information
   * @returns Promise<boolean> - Whether the request is authorized
   * @throws UnauthorizedException - When authentication fails
   */
  async canActivate(context: ExecutionContext): Promise<boolean> {
    const operationId = `bytebotd-jwt-auth-${Date.now()}-${Math.random().toString(36).substr(2, 6)}`;
    const startTime = Date.now();

    // Check if route is marked as public (skip authentication)
    const isPublic = this.reflector.getAllAndOverride<boolean>('isPublic', [
      context.getHandler(),
      context.getClass(),
    ]);

    if (isPublic) {
      this.logger.debug(
        `[${operationId}] Route marked as public, skipping authentication`,
        {
          operationId,
          route: this.getRouteInfo(context),
        },
      );
      return true;
    }

    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();
    const clientIp = this.getClientIpAddress(request);
    const userAgent = request.headers['user-agent']?.substring(0, 100);

    // Enhanced security logging with threat detection
    this.logger.debug(
      `[${operationId}] Enhanced JWT authentication attempt for computer control`,
      {
        operationId,
        method: request.method,
        url: request.url,
        userAgent,
        ipAddress: clientIp,
        timestamp: new Date().toISOString(),
        securityContext: 'computer_control_access',
      },
    );

    // Pre-authentication security checks
    if (!this.performPreAuthChecks(request, operationId)) {
      throw new UnauthorizedException(
        'Pre-authentication security check failed',
      );
    }

    try {
      // Call parent authentication logic (Passport JWT strategy)
      const _result = await super.canActivate(context); // Note: const reassignment issue fixed

      if (_result) {
        const authTime = Date.now() - startTime;
        const user = request.user;

        // Perform post-authentication security checks
        if (user && !this.performPostAuthChecks(user, operationId)) {
          throw new UnauthorizedException(
            'Post-authentication security check failed',
          );
        }

        this.logger.log(
          `[${operationId}] Enhanced JWT authentication successful for computer control`,
          {
            operationId,
            userId: user?.id,
            username: user?.username,
            role: user?.role,
            method: request.method,
            url: request.url,
            authTimeMs: authTime,
            ipAddress: clientIp,
            userAgent,
            securityLevel: 'enhanced',
            securityEvent: 'computer_control_auth_success',
            postAuthChecks: 'passed',
          },
        );
      }

      return _result as boolean;
    } catch (_error) {
      const authTime = Date.now() - startTime;

      // Log authentication failure with enhanced security context
      this.logger.warn(
        `[${operationId}] JWT authentication failed for computer control access`,
        {
          operationId,
          method: request.method,
          url: request.url,
          error: _error instanceof Error ? _error.message : String(_error),
          authTimeMs: authTime,
          ipAddress: this.getClientIpAddress(request),
          userAgent: request.headers['user-agent']?.substring(0, 100),
          hasAuthHeader: !!request.headers.authorization,
          authHeaderFormat: this.analyzeAuthHeader(
            request.headers.authorization,
          ),
          securityEvent: 'computer_control_auth_failed',
          riskScore: 85, // High risk for computer control access attempts
        },
      );

      // Re-throw as UnauthorizedException for consistent error handling
      if (_error instanceof UnauthorizedException) {
        throw _error;
      }

      throw new UnauthorizedException(
        'Authentication required for computer control',
      );
    }
  }

  /**
   * Handle authentication request and provide detailed error information
   * Called by Passport strategy when authentication fails
   *
   * @param err - Authentication error
   * @param user - Authenticated user (if successful)
   * @param info - Additional authentication information
   * @param context - Execution context
   * @returns User object or throws UnauthorizedException
   */
  handleRequest<TUser = ByteBotdUser>(
    err: JwtAuthError | null,
    user: ByteBotdUser | false,
    info: JwtAuthInfo | null,
    context: ExecutionContext,
  ): TUser {
    const operationId = `bytebotd-jwt-handle-${Date.now()}`;
    const request = context.switchToHttp().getRequest<AuthenticatedRequest>();

    // Handle authentication errors
    if (err) {
      this.logger.error(
        `[${operationId}] Computer control authentication error`,
        {
          operationId,
          _error: err instanceof Error ? err.message : String(err),
          stack: err instanceof Error ? err.stack : undefined,
          url: request.url,
          method: request.method,
          ipAddress: this.getClientIpAddress(request),
          securityEvent: 'computer_control_auth_error',
        },
      );
      throw new UnauthorizedException(
        'Authentication failed for computer control',
      );
    }

    // Handle missing or invalid user
    if (!user) {
      const errorMessage = this.getAuthErrorMessage(info);

      this.logger.warn(
        `[${operationId}] Computer control authentication failed - no user`,
        {
          operationId,
          info: info?.message ?? info?.name ?? String(info),
          url: request.url,
          method: request.method,
          ipAddress: this.getClientIpAddress(request),
          errorMessage,
          securityEvent: 'computer_control_no_user',
        },
      );

      throw new UnauthorizedException(errorMessage);
    }

    // Successful authentication
    this.logger.debug(
      `[${operationId}] Computer control authentication request handled successfully`,
      {
        operationId,
        userId: (user as ByteBotdUser).id,
        username: (user as ByteBotdUser).username,
        role: (user as ByteBotdUser).role,
        url: request.url,
        method: request.method,
        securityEvent: 'computer_control_auth_handled',
      },
    );

    return user as TUser;
  }

  /**
   * Extract client IP address from request
   * Handles various proxy configurations and headers
   *
   * @param request - HTTP request object
   * @returns string - Client IP address
   * @private
   */
  private getClientIpAddress(request: Request): string {
    return (
      (request.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ??
      (request.headers['x-real-ip'] as string) ??
      request.connection?.remoteAddress ??
      request.socket?.remoteAddress ??
      'unknown'
    );
  }

  /**
   * Get route information for logging
   * Extracts handler and controller information
   *
   * @param context - Execution context
   * @returns string - Route identifier
   * @private
   */
  private getRouteInfo(context: ExecutionContext): string {
    const handler = context.getHandler().name;
    const controller = context.getClass().name;
    return `${controller}.${handler}`;
  }

  /**
   * Analyze Authorization header format for debugging
   * Helps identify common authentication issues
   *
   * @param authHeader - Authorization header value
   * @returns string - Analysis result
   * @private
   */
  private analyzeAuthHeader(authHeader?: string): string {
    if (!authHeader) {
      return 'missing';
    }

    if (!authHeader.startsWith('Bearer ')) {
      return `invalid-format-${authHeader.split(' ')[0] ?? 'no-type'}`;
    }

    const token = authHeader.substring(7);
    if (!token) {
      return 'missing-token';
    }

    // Basic JWT format validation
    const parts = token.split('.');
    if (parts.length !== 3) {
      return `invalid-jwt-parts-${parts.length}`;
    }

    return 'valid-format';
  }

  /**
   * Get user-friendly authentication error message
   * Provides clear error messages for common authentication failures
   *
   * @param info - Passport authentication info object
   * @returns string - User-friendly error message
   * @private
   */
  private getAuthErrorMessage(info: unknown): string {
    if (!info) {
      return 'Authentication required for computer control';
    }

    const message = info?.message ?? info?.name ?? String(info);

    // Common JWT errors with user-friendly messages
    switch (message) {
      case 'TokenExpiredError':
      case 'jwt expired':
        return 'Access token has expired';

      case 'JsonWebTokenError':
      case 'invalid token':
        return 'Invalid access token';

      case 'NotBeforeError':
        return 'Token not active yet';

      case 'No auth token':
        return 'Access token required for computer control';

      default:
        return 'Authentication failed for computer control';
    }
  }

  /**
   * Enhanced pre-authentication security checks
   * Validates request headers, IP patterns, and potential security threats
   *
   * @param request - HTTP request object
   * @param operationId - Operation tracking ID
   * @returns boolean - Whether pre-auth checks passed
   * @private
   */
  private performPreAuthChecks(request: Request, operationId: string): boolean {
    // Check for suspicious user agent patterns
    const userAgent = request.headers['user-agent'];
    if (!userAgent ?? this.isSuspiciousUserAgent(userAgent)) {
      this.logger.warn(`[${operationId}] Suspicious user agent detected`, {
        operationId,
        userAgent,
        ipAddress: this.getClientIpAddress(request),
        securityEvent: 'suspicious_user_agent',
      });
      return false;
    }

    // Check for excessive header count (potential attack)
    const headerCount = Object.keys(request.headers).length;
    if (headerCount > 50) {
      this.logger.warn(`[${operationId}] Excessive headers detected`, {
        operationId,
        headerCount,
        ipAddress: this.getClientIpAddress(request),
        securityEvent: 'excessive_headers',
      });
      return false;
    }

    // Validate Authorization header format
    const authHeader = request.headers.authorization;
    if (authHeader && !this.isValidAuthHeaderFormat(authHeader)) {
      this.logger.warn(`[${operationId}] Invalid authorization header format`, {
        operationId,
        authHeaderFormat: this.analyzeAuthHeader(authHeader),
        ipAddress: this.getClientIpAddress(request),
        securityEvent: 'invalid_auth_header',
      });
      return false;
    }

    // Check for potential token replay attacks (basic timing check)
    if (authHeader && this.isPotentialReplayAttack(authHeader, operationId)) {
      this.logger.warn(
        `[${operationId}] Potential token replay attack detected`,
        {
          operationId,
          ipAddress: this.getClientIpAddress(request),
          securityEvent: 'potential_replay_attack',
        },
      );
      return false;
    }

    return true;
  }

  /**
   * Check if user agent indicates suspicious activity
   * Detects bots, scrapers, and automated tools
   *
   * @param userAgent - User agent string
   * @returns boolean - Whether user agent is suspicious
   * @private
   */
  private isSuspiciousUserAgent(userAgent: string): boolean {
    const suspiciousPatterns = [
      // Common bots and scrapers
      /bot|crawler|spider|scraper/gi,

      // Automated tools
      /curl|wget|httpie|postman|insomnia/gi,

      // Security scanners
      /nmap|nikto|sqlmap|burp|zap|acunetix|nessus/gi,

      // Generic HTTP clients
      /^(python|java|go|rust|php|ruby|perl)-/gi,

      // Empty or very short user agents
      /^.{0,10}$/,

      // Common attack tools
      /metasploit|exploit|payload|shell/gi,
    ];

    return suspiciousPatterns.some((pattern) => pattern.test(userAgent));
  }

  /**
   * Validate authorization header format
   * Ensures proper Bearer token format
   *
   * @param authHeader - Authorization header value
   * @returns boolean - Whether format is valid
   * @private
   */
  private isValidAuthHeaderFormat(authHeader: string): boolean {
    // Must be Bearer token format
    if (!authHeader.startsWith('Bearer ')) {
      return false;
    }

    const token = authHeader.substring(7);

    // Token must exist and be reasonable length
    if (!token ?? token.length < 20 ?? token.length > 2048) {
      return false;
    }

    // Basic JWT format check (3 parts separated by dots)
    const parts = token.split('.');
    if (parts.length !== 3) {
      return false;
    }

    // Each part should be base64url encoded (basic check)
    return parts.every(
      (part) => /^[A-Za-z0-9_-]+$/.test(part) && part.length > 0,
    );
  }

  /**
   * Basic replay attack detection using timing analysis
   * This is a simplified approach - production systems should use nonces
   *
   * @param authHeader - Authorization header value
   * @param operationId - Operation tracking ID
   * @returns boolean - Whether this might be a replay attack
   * @private
   */
  private isPotentialReplayAttack(
    authHeader: string,
    operationId: string,
  ): boolean {
    try {
      const token = authHeader.substring(7);
      const tokenParts = token.split('.');

      if (tokenParts.length !== 3) {
        return false;
      }

      // Decode JWT payload (without verification - just for timing check)
      // Convert base64url to base64 and decode
      const payloadPart = tokenParts[1];
      if (!payloadPart) {
        return false;
      }
      const base64Payload = payloadPart.replace(/-/g, '+').replace(/_/g, '/');
      const payload = JSON.parse(
        Buffer.from(base64Payload, 'base64').toString('utf8'),
      ) as StandardJwtPayload;

      const currentTime = Math.floor(Date.now() / 1000);
      const tokenIssuedAt = payload.iat;
      const tokenExpiry = payload.exp;

      // Check if token is very close to expiry (potential replay)
      if (tokenExpiry && currentTime > tokenExpiry - 60) {
        return true;
      }

      // Check if token was issued very recently (less than 1 second ago)
      // This could indicate rapid successive requests with the same token
      if (tokenIssuedAt && currentTime - tokenIssuedAt < 1) {
        return true;
      }
    } catch (_error) {
      // If we can't decode the token, let the main JWT validation handle it
      this.logger.debug(
        `[${operationId}] Could not decode JWT for replay check: ${_error instanceof Error ? _error.message : String(_error)}`,
      );
    }

    return false;
  }

  /**
   * Enhanced post-authentication user validation
   * Performs additional security checks on authenticated user
   *
   * @param user - Authenticated user object
   * @param operationId - Operation tracking ID
   * @returns boolean - Whether user passed additional security checks
   * @private
   */
  private performPostAuthChecks(
    user: ByteBotdUser,
    operationId: string,
  ): boolean {
    // Check if user account is active
    if (!user.isActive) {
      this.logger.warn(`[${operationId}] Inactive user attempted access`, {
        operationId,
        userId: user.id,
        username: user.username,
        securityEvent: 'inactive_user_access',
      });
      return false;
    }

    // Check user role permissions for computer control
    const allowedRoles: UserRole[] = [UserRole._ADMIN, UserRole._OPERATOR];
    if (!allowedRoles.includes(user.role)) {
      this.logger.warn(
        `[${operationId}] Unauthorized role attempted computer control access`,
        {
          operationId,
          userId: user.id,
          username: user.username,
          role: user.role,
          securityEvent: 'unauthorized_role_access',
        },
      );
      return false;
    }

    // Additional security validations can be added here
    // - Account lockout checks
    // - Concurrent session limits
    // - Geographic location validation
    // - Time-based access controls

    return true;
  }
}

/**
 * JWT Strategy - ByteBotd JWT Token Validation
 * Implements Passport JWT strategy for computer control authentication
 *
 * Features:
 * - JWT token validation with shared secret
 * - User payload extraction and validation
 * - Integration with shared security types
 * - Computer control specific security context
 *
 * @author Security Implementation Specialist
 * @version 1.0.0
 * @since ByteBotd Authentication Hardening
 */

import { Injectable, UnauthorizedException, Logger } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { UserRole } from '@bytebot/shared';
import { ByteBotdUser } from '../guards/jwt-auth.guard';

/**
 * JWT payload interface for ByteBotd authentication
 */
interface JwtPayload {
  sub: string; // User ID
  email: string;
  username: string;
  firstName?: string;
  lastName?: string;
  role: UserRole;
  isActive: boolean;
  iat: number; // Issued at
  exp: number; // Expires at
}

/**
 * JWT Strategy for ByteBotd computer control authentication
 * Validates JWT tokens and extracts user information
 */
@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  private readonly logger = new Logger(JwtStrategy.name);

  constructor() {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey:
        process.env.JWT_SECRET ?? 'bytebot-default-secret-change-in-production',
      algorithms: ['HS256'],
    });
  }

  /**
   * Validate JWT payload and extract user information
   * Called by Passport JWT strategy after token validation
   *
   * @param payload - Validated JWT payload
   * @returns Promise<ByteBotdUser> - User object for request context
   * @throws UnauthorizedException - When user is invalid or inactive
   */
  async validate(payload: JwtPayload): Promise<ByteBotdUser> {
    const operationId = `bytebotd-jwt-validate-${Date.now()}`;

    this.logger.debug(
      `[${operationId}] JWT payload validation for computer control`,
      {
        operationId,
        userId: payload.sub,
        username: payload.username,
        role: payload.role,
        isActive: payload.isActive,
        tokenIssuedAt: new Date(payload.iat * 1000),
        tokenExpiresAt: new Date(payload.exp * 1000),
        securityEvent: 'computer_control_jwt_validation',
      },
    );

    // Validate required payload fields
    if (!payload.sub ?? !payload.email ?? !payload.username ?? !payload.role) {
      this.logger.warn(
        `[${operationId}] Invalid JWT payload - missing required fields`,
        {
          operationId,
          userId: payload.sub,
          hasEmail: !!payload.email,
          hasUsername: !!payload.username,
          hasRole: !!payload.role,
          securityEvent: 'computer_control_invalid_jwt_payload',
        },
      );
      throw new UnauthorizedException('Invalid token payload');
    }

    // Check if user is active
    if (!payload.isActive) {
      this.logger.warn(
        `[${operationId}] Inactive user attempting computer control access`,
        {
          operationId,
          userId: payload.sub,
          username: payload.username,
          role: payload.role,
          securityEvent: 'computer_control_inactive_user_access',
          riskScore: 75,
        },
      );
      throw new UnauthorizedException('Account is inactive');
    }

    // Create user object for request context
    const user: ByteBotdUser = {
      id: payload.sub,
      email: payload.email,
      username: payload.username,
      firstName: payload.firstName,
      lastName: payload.lastName,
      role: payload.role,
      isActive: payload.isActive,
    };

    this.logger.debug(
      `[${operationId}] JWT validation successful for computer control`,
      {
        operationId,
        userId: user.id,
        username: user.username,
        role: user.role,
        securityEvent: 'computer_control_jwt_validated',
      },
    );

    return user;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { v4 as uuidv4 } from 'uuid';
import { BrowserUseService } from './browser-use.service';
import { BrowserTaskService } from './browser-task.service';
import {
  CreateAsyncJobDto,
  AsyncJobResultDto,
  AsyncJobStatus,
  AsyncJobType,
  AsyncJobPriority,
} from './dto/async-job.dto';
import {
  CreateBrowserTaskDto as _CreateBrowserTaskDto,
  BrowserTaskStatus as _BrowserTaskStatus,
} from './dto/browser-task.dto';

/**
 * Task configuration interface with proper typing
 */
interface TaskConfig {
  name: string;
  url?: string;
  selectors?: string[];
  actions?: string[];
  timeout?: number;
  [key: string]: unknown;
}

/**
 * Job configuration with tasks array properly typed
 */
interface TypedJobConfiguration {
  tasks?: TaskConfig[];
  urls?: string[];
  [key: string]: unknown;
}

/**
 * Standard error interface for error handling
 */
interface StandardError {
  message: string;
  name: string;
  stack?: string;
  [key: string]: unknown;
}

/**
 * Browser Async Job Service - Long-Running Task Management
 *
 * Manages asynchronous browser automation jobs that may take extended time to complete.
 * Provides queue management, progress monitoring, and resource optimization for
 * complex browser automation workflows.
 *
 * Key Responsibilities:
 * - Async job lifecycle management
 * - Queue processing and prioritization
 * - Progress monitoring and reporting
 * - Resource allocation and cleanup
 * - Batch processing coordination
 * - Error recovery and retry logic
 */
@Injectable()
export class BrowserAsyncJobService {
  private readonly logger = new Logger(BrowserAsyncJobService.name);
  private readonly jobs: Map<string, AsyncJobResultDto> = new Map();
  private readonly jobQueue: string[] = [];
  private readonly processingJobs = new Set<string>();
  private readonly maxConcurrentJobs = 3;
  private readonly jobProcessingInterval: NodeJS.Timeout;

  constructor(
    private readonly browserService: BrowserUseService,
    private readonly taskService: BrowserTaskService,
  ) {
    // Start job processor
    this.jobProcessingInterval = setInterval(() => {
      this.processJobQueue().catch((err) => {
        this.logger.error('Job queue processing failed', err);
      });
    }, 5000); // Check every 5 seconds

    this.logger.log('Browser Async Job Service initialized');
  }

  /**
   * Create a new async job
   */
  async createAsyncJob(_dto: CreateAsyncJobDto): Promise<AsyncJobResultDto> {
    const jobId = uuidv4();
    const now = new Date();

    this.logger.log(`Creating async job: ${_dto.name}`, {
      jobId,
      name: _dto.name,
      jobType: _dto.jobType,
      priority: _dto.priority,
      estimatedDurationMs: _dto.estimatedDurationMs,
    });

    try {
      const job: AsyncJobResultDto = {
        jobId,
        name: _dto.name,
        description: _dto.description,
        jobType: _dto.jobType,
        status: AsyncJobStatus.QUEUED,
        priority: _dto.priority ?? AsyncJobPriority.NORMAL,
        progress: {
          currentStep: 'Job queued for processing',
          completedSteps: 0,
          totalSteps: this.estimateTotalSteps(_dto),
          percentage: 0,
          estimatedRemainingMs: _dto.estimatedDurationMs ?? 300000,
        },
        createdAt: now,
        queuedAt: now,
        estimatedDurationMs: _dto.estimatedDurationMs ?? 300000,
        configuration: _dto.configuration,
        results: {
          tasksCompleted: 0,
          totalTasks: 0,
          screenshots: [],
          extractedData: {},
          logs: [],
        },
        metadata: {
          retryCount: 0,
          maxRetries: _dto.maxRetries ?? 3,
          createdBy: 'browser-automation-api',
          tags: _dto.tags ?? [],
          ..._dto.metadata,
        },
      };

      // Store job
      this.jobs.set(jobId, job);

      // Add to priority queue
      this.addToQueue(jobId);

      this.logger.log(`Async job created and queued: ${jobId}`, {
        jobId,
        status: job.status,
        queuePosition: this.getQueuePosition(jobId),
      });

      return job;
    } catch (_err) {
      this.logger.error(`Failed to create async job: ${_dto.name}`, _err);
      throw _err;
    }
  }

  /**
   * Get async job by ID
   */
  async getAsyncJob(jobId: string): Promise<AsyncJobResultDto | null> {
    const job = this.jobs.get(jobId);

    if (!job) {
      return null;
    }

    // Update progress for running jobs
    if (job.status === AsyncJobStatus.RUNNING) {
      await this.updateJobProgress(jobId);
    }

    return job;
  }

  /**
   * Get all async jobs
   */
  async getAllAsyncJobs(): Promise<AsyncJobResultDto[]> {
    const jobs = Array.from(this.jobs.values());

    // Update progress for running jobs
    const runningJobs = jobs.filter(
      (job) => job.status === AsyncJobStatus.RUNNING,
    );
    for (const job of runningJobs) {
      await this.updateJobProgress(job.jobId);
    }

    return jobs;
  }

  /**
   * Cancel async job
   */
  async cancelAsyncJob(jobId: string): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job) {
      throw new Error(`Async job not found: ${jobId}`);
    }

    if (
      job.status === AsyncJobStatus.COMPLETED ||
      job.status === AsyncJobStatus.FAILED ||
      job.status === AsyncJobStatus.CANCELLED
    ) {
      throw new Error(`Cannot cancel job in status: ${job.status}`);
    }

    this.logger.log(`Cancelling async job: ${jobId}`, {
      jobId,
      currentStatus: job.status,
    });

    // Store the current status before updating
    const wasRunning = job.status === AsyncJobStatus.RUNNING;

    // Update job status
    job.status = AsyncJobStatus.CANCELLED;
    job.completedAt = new Date();
    job.progress.currentStep = 'Job cancelled by user';

    // Add cancellation log
    job.results.logs.push({
      timestamp: new Date(),
      level: 'warn',
      message: 'Async job cancelled by user',
      metadata: {
        reason: 'user_cancellation',
        completedSteps: job.progress.completedSteps,
        totalSteps: job.progress.totalSteps,
      },
    });

    // Remove from queue if not yet started
    const queueIndex = this.jobQueue.indexOf(jobId);
    if (queueIndex >= 0) {
      this.jobQueue.splice(queueIndex, 1);
    }

    // Cancel associated tasks if was running
    if (wasRunning && job.taskIds) {
      for (const taskId of job.taskIds) {
        try {
          await this.taskService.cancelTask(taskId);
        } catch (_err) {
          this.logger.warn(`Failed to cancel associated task: ${taskId}`, _err);
        }
      }
    }

    // Remove from processing set
    this.processingJobs.delete(jobId);

    this.jobs.set(jobId, job);

    this.logger.log(`Async job cancelled: ${jobId}`, {
      jobId,
      completedSteps: job.progress.completedSteps,
      totalSteps: job.progress.totalSteps,
    });
  }

  /**
   * Delete completed job (cleanup)
   */
  async deleteAsyncJob(jobId: string): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    // Only allow deletion of completed, failed, or cancelled jobs
    if (
      job.status === AsyncJobStatus.RUNNING ||
      job.status === AsyncJobStatus.QUEUED
    ) {
      throw new Error(`Cannot delete job in status: ${job.status}`);
    }

    // Remove from queue if present
    const queueIndex = this.jobQueue.indexOf(jobId);
    if (queueIndex >= 0) {
      this.jobQueue.splice(queueIndex, 1);
    }

    // Delete associated tasks
    if (job.taskIds) {
      for (const taskId of job.taskIds) {
        try {
          await this.taskService.deleteTask(taskId);
        } catch (_err) {
          this.logger.warn(`Failed to delete associated task: ${taskId}`, _err);
        }
      }
    }

    // Delete job
    this.jobs.delete(jobId);

    this.logger.log(`Async job deleted: ${jobId}`, {
      jobId,
      status: job.status,
    });
  }

  /**
   * Get queue status and statistics
   */
  async getQueueStatus(): Promise<{
    queueLength: number;
    processingJobs: number;
    completedJobs: number;
    failedJobs: number;
    totalJobs: number;
    averageProcessingTime: number;
  }> {
    const jobs = Array.from(this.jobs.values());

    const completedJobs = jobs.filter(
      (j) => j.status === AsyncJobStatus.COMPLETED,
    );
    const failedJobs = jobs.filter((j) => j.status === AsyncJobStatus.FAILED);

    const totalProcessingTime = completedJobs.reduce((sum, job) => {
      if (job.startedAt && job.completedAt) {
        return sum + (job.completedAt.getTime() - job.startedAt.getTime());
      }
      return sum;
    }, 0);

    const averageProcessingTime =
      completedJobs.length > 0 ? totalProcessingTime / completedJobs.length : 0;

    return {
      queueLength: this.jobQueue.length,
      processingJobs: this.processingJobs.size,
      completedJobs: completedJobs.length,
      failedJobs: failedJobs.length,
      totalJobs: this.jobs.size,
      averageProcessingTime: Math.round(averageProcessingTime),
    };
  }

  /**
   * Clean up old jobs
   */
  async cleanupOldJobs(maxAge: number = 86400000): Promise<number> {
    // 24 hours default
    const now = Date.now();
    let cleanedCount = 0;

    for (const [jobId, job] of this.jobs.entries()) {
      // Skip active jobs
      if (
        job.status === AsyncJobStatus.RUNNING ||
        job.status === AsyncJobStatus.QUEUED
      ) {
        continue;
      }

      // Check age
      const jobAge = job.completedAt
        ? now - job.completedAt.getTime()
        : now - job.createdAt.getTime();

      if (jobAge > maxAge) {
        await this.deleteAsyncJob(jobId);
        cleanedCount++;
      }
    }

    if (cleanedCount > 0) {
      this.logger.log(`Cleaned up ${cleanedCount} old async jobs`, {
        cleanedCount,
        maxAgeHours: maxAge / (1000 * 60 * 60),
        remainingJobs: this.jobs.size,
      });
    }

    return cleanedCount;
  }

  // ===========================
  // PRIVATE METHODS
  // ===========================

  /**
   * Process job queue
   */
  private async processJobQueue(): Promise<void> {
    // Check if we can process more jobs
    if (this.processingJobs.size >= this.maxConcurrentJobs) {
      return;
    }

    // Get next job from queue
    const jobId = this.getNextJobFromQueue();
    if (!jobId) {
      return;
    }

    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    // Start processing job
    this.processingJobs.add(jobId);

    this.logger.log(`Starting async job processing: ${jobId}`, {
      jobId,
      jobType: job.jobType,
      priority: job.priority,
    });

    try {
      await this.processJob(job);
    } catch (_err) {
      this.logger.error(`Job processing failed: ${jobId}`, _err);
      await this.handleJobFailure(jobId, _err);
    } finally {
      this.processingJobs.delete(jobId);
    }
  }

  /**
   * Process individual job
   */
  private async processJob(job: AsyncJobResultDto): Promise<void> {
    // Update job status
    job.status = AsyncJobStatus.RUNNING;
    job.startedAt = new Date();
    job.progress.currentStep = 'Initializing job processing';

    this.jobs.set(job.jobId, job);

    switch (job.jobType) {
      case AsyncJobType.BATCH_AUTOMATION:
        await this.processBatchAutomation(job);
        break;

      case AsyncJobType.DATA_EXTRACTION:
        await this.processDataExtraction(job);
        break;

      case AsyncJobType.FORM_FILLING:
        await this.processFormFilling(job);
        break;

      case AsyncJobType.SCREENSHOT_CAPTURE:
        await this.processScreenshotCapture(job);
        break;

      case AsyncJobType.CUSTOM_WORKFLOW:
        await this.processCustomWorkflow(job);
        break;

      default:
        throw new Error(`Unsupported job type: ${job.jobType}`);
    }

    // Mark job as completed
    await this.completeJob(job);
  }

  /**
   * Process batch automation job
   */
  private async processBatchAutomation(job: AsyncJobResultDto): Promise<void> {
    const config = job.configuration as TypedJobConfiguration;
    const tasks = Array.isArray(config.tasks)
      ? config.tasks
      : ([] as TaskConfig[]);

    job.progress.totalSteps = tasks.length;
    job.results.totalTasks = tasks.length;

    for (let i = 0; i < tasks.length; i++) {
      const taskConfig = tasks[i];

      job.progress.currentStep = `Processing task ${i + 1}/${tasks.length}: ${taskConfig.name}`;
      job.progress.completedSteps = i;
      job.progress.percentage = Math.round((i / tasks.length) * 100);

      this.jobs.set(job.jobId, job);

      try {
        const taskResult =
          await this.browserService.executeBrowserTask(taskConfig);

        // Store task ID for tracking
        if (!job.taskIds) {
          job.taskIds = [];
        }
        job.taskIds.push(taskResult.taskId);

        // Collect results
        if (taskResult.screenshots) {
          job.results.screenshots.push(...taskResult.screenshots);
        }

        if (taskResult.extractedData) {
          job.results.extractedData[`task_${i}`] = taskResult.extractedData;
        }

        job.results.tasksCompleted++;

        job.results.logs.push({
          timestamp: new Date(),
          level: 'info',
          message: `Task completed: ${taskConfig.name}`,
          metadata: {
            taskIndex: i,
            taskId: taskResult.taskId,
            status: taskResult.status,
          },
        });
      } catch (_err) {
        job.results.logs.push({
          timestamp: new Date(),
          level: 'error',
          message: `Task failed: ${taskConfig.name}`,
          metadata: {
            taskIndex: i,
            error: _err instanceof Error ? _err.message : String(_err),
          },
        });

        // Continue with next task unless configured to stop on error
        if (!config.continueOnError) {
          throw _err;
        }
      }
    }
  }

  /**
   * Process data extraction job
   */
  private async processDataExtraction(job: AsyncJobResultDto): Promise<void> {
    const config = job.configuration as TypedJobConfiguration;
    const urls = Array.isArray(config.urls) ? config.urls : ([] as string[]);

    job.progress.totalSteps = urls.length;

    for (let i = 0; i < urls.length; i++) {
      const url = urls[i];

      job.progress.currentStep = `Extracting data from ${url}`;
      job.progress.completedSteps = i;
      job.progress.percentage = Math.round((i / urls.length) * 100);

      this.jobs.set(job.jobId, job);

      try {
        // Create session for data extraction
        const sessionId = await this.createExtractionSession();

        const extractedData = await this.browserService.extractPageData(
          sessionId,
          {
            selectors:
              typeof config.selectors === 'object' &&
              config.selectors !== null &&
              !Array.isArray(config.selectors)
                ? config.selectors
                : {},
            waitForSelector:
              typeof config.waitForSelector === 'string'
                ? config.waitForSelector
                : undefined,
            timeout: config.timeout ?? 30000,
          },
        );

        job.results.extractedData[url] = extractedData;

        job.results.logs.push({
          timestamp: new Date(),
          level: 'info',
          message: `Data extracted from: ${url}`,
          metadata: {
            url,
            dataKeys: Object.keys(extractedData).length,
          },
        });
      } catch (_err) {
        job.results.logs.push({
          timestamp: new Date(),
          level: 'error',
          message: `Data extraction failed for: ${url}`,
          metadata: {
            url,
            error: _err instanceof Error ? _err.message : String(_err),
          },
        });

        if (!config.continueOnError) {
          throw _err;
        }
      }
    }
  }

  /**
   * Process other job types (placeholder implementations)
   */
  private async processFormFilling(job: AsyncJobResultDto): Promise<void> {
    // Implementation for form filling jobs
    job.progress.currentStep = 'Processing form filling job';
    job.progress.completedSteps = 1;
    job.progress.totalSteps = 1;
    job.progress.percentage = 100;
  }

  private async processScreenshotCapture(
    job: AsyncJobResultDto,
  ): Promise<void> {
    // Implementation for screenshot capture jobs
    job.progress.currentStep = 'Processing screenshot capture job';
    job.progress.completedSteps = 1;
    job.progress.totalSteps = 1;
    job.progress.percentage = 100;
  }

  private async processCustomWorkflow(job: AsyncJobResultDto): Promise<void> {
    // Implementation for custom workflow jobs
    job.progress.currentStep = 'Processing custom workflow job';
    job.progress.completedSteps = 1;
    job.progress.totalSteps = 1;
    job.progress.percentage = 100;
  }

  /**
   * Complete job processing
   */
  private async completeJob(job: AsyncJobResultDto): Promise<void> {
    job.status = AsyncJobStatus.COMPLETED;
    job.completedAt = new Date();
    job.progress.currentStep = 'Job completed successfully';
    job.progress.percentage = 100;

    if (job.startedAt) {
      job.actualDurationMs =
        job.completedAt.getTime() - job.startedAt.getTime();
    }

    job.results.logs.push({
      timestamp: new Date(),
      level: 'info',
      message: 'Async job completed successfully',
      metadata: {
        tasksCompleted: job.results.tasksCompleted,
        totalTasks: job.results.totalTasks,
        actualDurationMs: job.actualDurationMs,
      },
    });

    this.jobs.set(job.jobId, job);

    this.logger.log(`Async job completed: ${job.jobId}`, {
      jobId: job.jobId,
      actualDurationMs: job.actualDurationMs,
      tasksCompleted: job.results.tasksCompleted,
    });
  }

  /**
   * Handle job failure
   */
  private async handleJobFailure(
    jobId: string,
    error: StandardError | Error | unknown,
  ): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    job.status = AsyncJobStatus.FAILED;
    job.completedAt = new Date();
    job.errorMessage = error instanceof Error ? error.message : String(error);
    job.progress.currentStep = `Job failed: ${job.errorMessage}`;

    if (job.startedAt) {
      job.actualDurationMs =
        job.completedAt.getTime() - job.startedAt.getTime();
    }

    job.results.logs.push({
      timestamp: new Date(),
      level: 'error',
      message: 'Async job failed',
      metadata: {
        error: job.errorMessage,
        retryCount: job.metadata.retryCount,
        maxRetries: job.metadata.maxRetries,
      },
    });

    // Check if we should retry
    if (job.metadata.retryCount < job.metadata.maxRetries) {
      job.metadata.retryCount++;
      job.status = AsyncJobStatus.QUEUED;
      job.progress.currentStep = `Retrying job (attempt ${job.metadata.retryCount + 1}/${job.metadata.maxRetries + 1})`;

      // Add back to queue for retry
      this.addToQueue(jobId);

      this.logger.warn(`Job failed, retrying: ${jobId}`, {
        jobId,
        retryCount: job.metadata.retryCount,
        maxRetries: job.metadata.maxRetries,
      });
    } else {
      this.logger.error(`Job failed permanently: ${jobId}`, {
        jobId,
        error: job.errorMessage,
        retryCount: job.metadata.retryCount,
      });
    }

    this.jobs.set(jobId, job);
  }

  /**
   * Update job progress
   */
  private async updateJobProgress(jobId: string): Promise<void> {
    const job = this.jobs.get(jobId);
    if (!job || job.status !== AsyncJobStatus.RUNNING) {
      return;
    }

    // Update estimated remaining time
    if (job.startedAt && job.progress.completedSteps > 0) {
      const elapsed = Date.now() - job.startedAt.getTime();
      const avgTimePerStep = elapsed / job.progress.completedSteps;
      const remainingSteps =
        job.progress.totalSteps - job.progress.completedSteps;
      job.progress.estimatedRemainingMs = remainingSteps * avgTimePerStep;
    }

    this.jobs.set(jobId, job);
  }

  /**
   * Add job to priority queue
   */
  private addToQueue(jobId: string): void {
    const job = this.jobs.get(jobId);
    if (!job) {
      return;
    }

    // Insert based on priority
    const priorityOrder = {
      [AsyncJobPriority.CRITICAL]: 0,
      [AsyncJobPriority.URGENT]: 1,
      [AsyncJobPriority.HIGH]: 2,
      [AsyncJobPriority.NORMAL]: 3,
      [AsyncJobPriority.LOW]: 4,
    };

    const jobPriorityValue = priorityOrder[job.priority];
    let insertIndex = this.jobQueue.length;

    // Find correct insertion position
    for (let i = 0; i < this.jobQueue.length; i++) {
      const queuedJobId = this.jobQueue[i];
      if (!queuedJobId) continue;
      const queuedJob = this.jobs.get(queuedJobId);

      if (queuedJob) {
        const queuedPriorityValue = priorityOrder[queuedJob.priority];
        if (jobPriorityValue < queuedPriorityValue) {
          insertIndex = i;
          break;
        }
      }
    }

    this.jobQueue.splice(insertIndex, 0, jobId);

    this.logger.log(`Job added to queue: ${jobId}`, {
      jobId,
      priority: job.priority,
      queuePosition: insertIndex,
      queueLength: this.jobQueue.length,
    });
  }

  /**
   * Get next job from queue
   */
  private getNextJobFromQueue(): string | null {
    return this.jobQueue.shift() ?? null;
  }

  /**
   * Get queue position
   */
  private getQueuePosition(jobId: string): number {
    return this.jobQueue.indexOf(jobId);
  }

  /**
   * Estimate total steps for job
   */
  private estimateTotalSteps(_dto: CreateAsyncJobDto): number {
    switch (_dto.jobType) {
      case AsyncJobType.BATCH_AUTOMATION:
        return Array.isArray(_dto.configuration.tasks)
          ? _dto.configuration.tasks.length
          : 1;
      case AsyncJobType.DATA_EXTRACTION:
        return Array.isArray(_dto.configuration.urls)
          ? _dto.configuration.urls.length
          : 1;
      default:
        return 1;
    }
  }

  /**
   * Create session for extraction
   */
  private async createExtractionSession(): Promise<string> {
    // This would create a browser session for data extraction
    // For now, return a mock session ID
    return `extraction_session_${Date.now()}`;
  }

  /**
   * Cleanup on service destruction
   */
  onModuleDestroy() {
    if (this.jobProcessingInterval) {
      clearInterval(this.jobProcessingInterval);
    }

    // Cancel all running jobs
    for (const jobId of this.processingJobs) {
      this.cancelAsyncJob(jobId).catch((err) => {
        this.logger.error(
          `Failed to cancel job during shutdown: ${jobId}`,
          err,
        );
      });
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { spawn, ChildProcess as _ChildProcess } from 'child_process';
