// Mock function to simulate environment-specific configuration
function getSecurityConfigForEnvironment(env: string) {
  const baseConfig = {
    enableSanitization: true,
    enableXSSDetection: true,
    enableSQLInjectionDetection: true,
    enableLogging: true,
  };

  switch (env) {
    case 'production':
      return {
        ...baseConfig,
        strictMode: true,
        maxInputLength: 1000,
      };
    case 'staging':
      return {
        ...baseConfig,
        strictMode: true,
        maxInputLength: 5000,
      };
    case 'development':
      return {
        ...baseConfig,
        strictMode: false,
        maxInputLength: 10000,
      };
    default:
      return baseConfig;
  }
}

