/**
 * Enterprise Security Exception Filter - Secure Error Handling
 *
 * This filter provides comprehensive error handling with security-focused
 * response sanitization to prevent information disclosure while maintaining
 * proper error logging and monitoring for security incidents.
 *
 * @fileoverview Enterprise-grade secure error handling and response sanitization
 * @version 1.0.0
 * @author Input Validation & API Security Specialist
 */

/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable @typescript-eslint/no-unsafe-assignment */
/* eslint-disable @typescript-eslint/no-unsafe-argument */
/* eslint-disable @typescript-eslint/no-unsafe-member-access */


/* eslint-disable @typescript-eslint/prefer-nullish-coalescing */


import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { ThrottlerException } from '@nestjs/throttler';

/**
 * Security-focused error classification
 */
enum SecurityErrorType {
  VALIDATION_ERROR = 'validation_error',
  AUTHENTICATION_ERROR = 'authentication_error',
  AUTHORIZATION_ERROR = 'authorization_error',
  RATE_LIMIT_ERROR = 'rate_limit_error',
  SECURITY_VIOLATION = 'security_violation',
  SYSTEM_ERROR = 'system_error',
  INPUT_ERROR = 'input_error',
}

/**
 * Secure error response structure
 */
interface SecureErrorResponse {
  statusCode: number;
  error: string;
  message: string;
  timestamp: string;
  path: string;
  requestId: string;
  // Only include in development
  details?: any;
  stack?: string;
}

/**
 * Security metrics for error tracking
 */
interface _SecurityErrorMetrics {
  errorType: SecurityErrorType;
  statusCode: number;
  clientIP: string;
  userAgent: string;
  endpoint: string;
  timestamp: Date;
  riskScore: number;
}

@Catch()
export class SecurityExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(SecurityExceptionFilter.name);

  // Track error patterns for security analysis
  private errorPatterns = new Map<
    string,
    {
      count: number;
      lastSeen: Date;
      riskScore: number;
    }
  >();

  /**
   * Handle all exceptions with security-focused processing
   */
  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const request = ctx.getRequest<Request>();
    const response = ctx.getResponse<Response>();

    // Generate request ID for tracking (use existing or create new)
    const requestId =
      (request.headers['x-correlation-id'] as string) ||
      (request.headers['x-request-id'] as string) ||
      `error-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    // Classify and analyze the exception
    const errorAnalysis = this.analyzeException(exception, request);

    // Create secure error response (never leak sensitive info)
    const secureResponse = this.createSecureResponse(
      exception,
      request,
      requestId,
      errorAnalysis,
    );

    // Log security event with full details (for internal use)
    this.logSecurityEvent(exception, request, errorAnalysis, requestId);

    // Track error patterns for threat detection
    this.trackErrorPattern(request, errorAnalysis);

    // Check for security attack patterns
    if (errorAnalysis.riskScore >= 7) {
      this.handleHighRiskError(request, errorAnalysis, requestId);
    }

    // Set security headers
    response.setHeader('X-Request-ID', requestId);
    response.setHeader('X-Content-Type-Options', 'nosniff');
    response.setHeader('X-Frame-Options', 'DENY');

    // Send secure response
    response.status(secureResponse.statusCode).json(secureResponse);
  }

  /**
   * Analyze exception for security classification and risk assessment
   */
  private analyzeException(
    exception: unknown,
    request: Request,
  ): {
    errorType: SecurityErrorType;
    statusCode: number;
    riskScore: number;
    threatIndicators: string[];
    isSecurityRelated: boolean;
  } {
    let errorType = SecurityErrorType.SYSTEM_ERROR;
    let statusCode = HttpStatus.INTERNAL_SERVER_ERROR;
    let riskScore = 1;
    const threatIndicators: string[] = [];

    // Analyze exception type
    if (exception instanceof HttpException) {
      statusCode = exception.getStatus();

      // Classify by HTTP status code
      switch (statusCode) {
        case HttpStatus.BAD_REQUEST:
          errorType = SecurityErrorType.INPUT_ERROR;
          riskScore = 2;
          break;
        case HttpStatus.UNAUTHORIZED:
          errorType = SecurityErrorType.AUTHENTICATION_ERROR;
          riskScore = 4;
          threatIndicators.push('auth_failure');
          break;
        case HttpStatus.FORBIDDEN:
          errorType = SecurityErrorType.AUTHORIZATION_ERROR;
          riskScore = 5;
          threatIndicators.push('access_denied');
          break;
        case HttpStatus.TOO_MANY_REQUESTS:
          errorType = SecurityErrorType.RATE_LIMIT_ERROR;
          riskScore = 3;
          threatIndicators.push('rate_limit_exceeded');
          break;
        default:
          if (statusCode >= 400 && statusCode < 500) {
            riskScore = 3;
          }
      }

      // Check for specific exception types
      if (exception instanceof ThrottlerException) {
        errorType = SecurityErrorType.RATE_LIMIT_ERROR;
        riskScore = 4;
        threatIndicators.push('throttle_violation');
      }

      // Analyze error message for security patterns
      const message = exception.message?.toLowerCase() ?? '';

      if (message.includes('validation') ?? message.includes('sanitization')) {
        errorType = SecurityErrorType.VALIDATION_ERROR;
        riskScore += 1;
      }

      if (
        message.includes('xss') ||
        message.includes('injection') ||
        message.includes('malicious')
      ) {
        errorType = SecurityErrorType.SECURITY_VIOLATION;
        riskScore += 4;
        threatIndicators.push('attack_detected');
      }
    }

    // Increase risk score for repeated errors from same client
    const clientIdentifier = this.getClientIdentifier(request);
    const existingPattern = this.errorPatterns.get(clientIdentifier);
    if (existingPattern && existingPattern.count > 5) {
      riskScore += 2;
      threatIndicators.push('repeated_errors');
    }

    return {
      errorType,
      statusCode,
      riskScore: Math.min(10, riskScore), // Cap at 10
      threatIndicators,
      isSecurityRelated: riskScore >= 4 ?? threatIndicators.length > 0,
    };
  }

  /**
   * Create secure error response that doesn't leak sensitive information
   */
  private createSecureResponse(
    exception: unknown,
    request: Request,
    requestId: string,
    errorAnalysis: any,
  ): SecureErrorResponse {
    const isDevelopment = process.env.NODE_ENV === 'development';

    // Base secure response
    const response: SecureErrorResponse = {
      statusCode: errorAnalysis.statusCode,
      error: this.getSecureErrorName(errorAnalysis.statusCode),
      message: this.getSecureErrorMessage(exception, errorAnalysis),
      timestamp: new Date().toISOString(),
      path: request.path,
      requestId,
    };

    // Only include detailed information in development
    if (isDevelopment) {
      response.details = this.sanitizeErrorDetails(exception);

      if (exception instanceof Error && exception.stack) {
        response.stack = exception.stack;
      }
    }

    return response;
  }

  /**
   * Get secure error name based on status code
   */
  private getSecureErrorName(statusCode: number): string {
    const errorNames: Record<number, string> = {
      400: 'Bad Request',
      401: 'Unauthorized',
      403: 'Forbidden',
      404: 'Not Found',
      405: 'Method Not Allowed',
      409: 'Conflict',
      422: 'Unprocessable Entity',
      429: 'Too Many Requests',
      500: 'Internal Server Error',
      502: 'Bad Gateway',
      503: 'Service Unavailable',
      504: 'Gateway Timeout',
    };

    return errorNames[statusCode] ?? 'Unknown Error';
  }

  /**
   * Get secure error message that doesn't leak sensitive information
   */
  private getSecureErrorMessage(
    exception: unknown,
    errorAnalysis: any,
  ): string {
    // For security violations, use generic message
    if (errorAnalysis.errorType === SecurityErrorType.SECURITY_VIOLATION) {
      return 'Request blocked due to security policy violation';
    }

    // For rate limiting
    if (errorAnalysis.errorType === SecurityErrorType.RATE_LIMIT_ERROR) {
      return 'Too many requests. Please try again later';
    }

    // For validation errors, provide safe message
    if (errorAnalysis.errorType === SecurityErrorType.VALIDATION_ERROR) {
      return 'Invalid input provided. Please check your request';
    }

    // For HTTP exceptions, use the message but sanitize it
    if (exception instanceof HttpException) {
      const message = exception.message;
      return this.sanitizeErrorMessage(message);
    }

    // Generic message for other errors
    return 'An error occurred while processing your request';
  }

  /**
   * Sanitize error message to prevent information disclosure
   */
  private sanitizeErrorMessage(message: string): string {
    // Remove sensitive patterns
    const sanitizedMessage = message
      // Remove file paths
      .replace(/\/[a-zA-Z0-9/_-]+/g, '[PATH_REMOVED]')
      // Remove database information
      .replace(/database|table|column|sql|query/gi, '[DB_INFO_REMOVED]')
      // Remove system information
      .replace(/system|process|memory|cpu/gi, '[SYSTEM_INFO_REMOVED]')
      // Remove stack traces
      .replace(/at [a-zA-Z0-9._]+\([^)]+\)/g, '[STACK_REMOVED]')
      // Remove sensitive environment variables
      .replace(
        /NODE_ENV|API_KEY|SECRET|PASSWORD|TOKEN/gi,
        '[SENSITIVE_REMOVED]',
      );

    return sanitizedMessage.substring(0, 200); // Limit message length
  }

  /**
   * Sanitize error details for development responses
   */
  private sanitizeErrorDetails(exception: unknown): any {
    if (!(exception instanceof Error)) {
      return null;
    }

    return {
      name: exception.name,
      cause: (exception as any).cause ?? 'Unknown',
      // Don't include the full stack trace in JSON response
    };
  }

  /**
   * Log security event with full details for monitoring
   */
  private logSecurityEvent(
    exception: unknown,
    request: Request,
    errorAnalysis: any,
    requestId: string,
  ): void {
    const logData = {
      event: 'security_exception',
      requestId,
      errorType: errorAnalysis.errorType,
      statusCode: errorAnalysis.statusCode,
      riskScore: errorAnalysis.riskScore,
      threatIndicators: errorAnalysis.threatIndicators,
      isSecurityRelated: errorAnalysis.isSecurityRelated,
      request: {
        method: request.method,
        url: request.url,
        path: request.path,
        query: request.query,
        headers: this.sanitizeHeaders(request.headers),
        clientIP: this.getClientIP(request),
        userAgent: request.headers['user-agent'],
      },
      exception: {
        name: exception instanceof Error ? exception.name : 'Unknown',
        message:
          exception instanceof Error ? exception.message : String(exception),
        stack: exception instanceof Error ? exception.stack : undefined,
      },
      timestamp: new Date().toISOString(),
    };

    // Log at appropriate level based on risk score
    if (errorAnalysis.riskScore >= 7) {
      this.logger.error(`[${requestId}] HIGH RISK SECURITY EXCEPTION`, logData);
    } else if (errorAnalysis.isSecurityRelated) {
      this.logger.warn(`[${requestId}] Security-related exception`, logData);
    } else {
      this.logger.debug(`[${requestId}] Application exception`, logData);
    }
  }

  /**
   * Track error patterns for threat detection
   */
  private trackErrorPattern(request: Request, errorAnalysis: any): void {
    const clientIdentifier = this.getClientIdentifier(request);
    const now = new Date();

    if (!this.errorPatterns.has(clientIdentifier)) {
      this.errorPatterns.set(clientIdentifier, {
        count: 1,
        lastSeen: now,
        riskScore: errorAnalysis.riskScore,
      });
    } else {
      const pattern = this.errorPatterns.get(clientIdentifier)!;
      pattern.count += 1;
      pattern.lastSeen = now;
      pattern.riskScore = Math.max(pattern.riskScore, errorAnalysis.riskScore);
    }

    // Clean up old patterns (older than 1 hour)
    this.cleanupErrorPatterns();
  }

  /**
   * Handle high-risk security errors
   */
  private handleHighRiskError(
    request: Request,
    errorAnalysis: any,
    requestId: string,
  ): void {
    const clientIP = this.getClientIP(request);
    const userAgent = request.headers['user-agent'];

    this.logger.error(`[${requestId}] HIGH RISK SECURITY EVENT DETECTED`, {
      event: 'high_risk_error',
      requestId,
      clientIP,
      userAgent,
      endpoint: request.path,
      riskScore: errorAnalysis.riskScore,
      threatIndicators: errorAnalysis.threatIndicators,
      recommendation:
        'Consider implementing additional security measures for this client',
      timestamp: new Date().toISOString(),
    });

    // In a production environment, you might:
    // - Send alert to security team
    // - Add IP to temporary blocklist
    // - Increase monitoring for this client
    // - Trigger additional security measures
  }

  /**
   * Generate client identifier for tracking
   */
  private getClientIdentifier(request: Request): string {
    const ip = this.getClientIP(request);
    const userAgent = (request.headers['user-agent'] ?? '').substring(0, 50);
    return `${ip}:${userAgent}`.replace(/[^a-zA-Z0-9:.-]/g, '_');
  }

  /**
   * Get client IP address
   */
  private getClientIP(request: Request): string {
    return (
      (request.headers['x-forwarded-for'] as string)?.split(',')[0] ||
      (request.headers['x-real-ip'] as string) ||
      request.connection.remoteAddress ||
      request.socket.remoteAddress ||
      'unknown'
    );
  }

  /**
   * Sanitize headers to remove sensitive information
   */
  private sanitizeHeaders(headers: any): any {
    const sanitized = { ...headers };

    const sensitiveHeaders = [
      'authorization',
      'cookie',
      'x-api-key',
      'x-auth-token',
      'proxy-authorization',
    ];

    sensitiveHeaders.forEach((header) => {
      if (sanitized[header]) {
        sanitized[header] = '[REDACTED]';
      }
    });

    return sanitized;
  }

  /**
   * Clean up old error patterns
   */
  private cleanupErrorPatterns(): void {
    const now = Date.now();
    const maxAge = 60 * 60 * 1000; // 1 hour

    // Convert to array to avoid iterator issues
    const entries = Array.from(this.errorPatterns.entries());
    for (const [key, pattern] of entries) {
      if (now - pattern.lastSeen.getTime() > maxAge) {
        this.errorPatterns.delete(key);
      }
    }
  }

  /**
   * Get current error pattern statistics (for monitoring)
   */
  getErrorPatternStats(): {
    totalClients: number;
    highRiskClients: number;
    topErrorClients: Array<{
      client: string;
      count: number;
      riskScore: number;
      lastSeen: Date;
    }>;
  } {
    const highRiskClients = Array.from(this.errorPatterns.entries()).filter(
      ([, pattern]) => pattern.riskScore >= 6,
    ).length;

    const topErrorClients = Array.from(this.errorPatterns.entries())
      .sort(([, a], [, b]) => b.count - a.count)
      .slice(0, 10)
      .map(([client, pattern]) => ({
        client: client.substring(0, 30) + '...', // Truncate for privacy
        count: pattern.count,
        riskScore: pattern.riskScore,
        lastSeen: pattern.lastSeen,
      }));

    return {
      totalClients: this.errorPatterns.size,
      highRiskClients,
      topErrorClients,
    };
  }
}

/**
 * Cache Interceptor - Intelligent API Response Caching
 *
 * Provides transparent caching for API endpoints with intelligent cache
 * strategies, conditional caching, and automatic invalidation. Designed
 * to maximize cache hit rates while maintaining data consistency.
 *
 * Features:
 * - Automatic cache key generation from request parameters
 * - Conditional caching based on response status and content
 * - TTL configuration per endpoint pattern
 * - Cache invalidation on mutations
 * - ETag and Last-Modified header support
 * - User-specific caching for personalized responses
 * - Comprehensive cache metrics and monitoring
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */







/* eslint-disable @typescript-eslint/prefer-nullish-coalescing */

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, tap } from 'rxjs';
import { Request, Response } from 'express';
import { CacheService } from '../../cache/cache.service';
import { CacheKeyGenerator } from '../../cache/cache-key.generator';
import { MetricsService } from '../../metrics/metrics.service';
import { createHash } from 'crypto';

/**
 * Cache configuration for different endpoint patterns
 */
interface CacheRule {
  pattern: RegExp;
  ttl: number; // Time to live in seconds
  varyBy?: string[]; // Request headers/params to vary cache by
  includeUserId?: boolean; // Include user ID in cache key
  cacheableStatuses?: number[]; // HTTP status codes that should be cached
  skipCacheIf?: (_req: Request, res: Response) => boolean; // Dynamic cache skipping
}

/**
 * Cache metadata stored with cached responses
 */
interface CacheMetadata {
  timestamp: number;
  etag?: string;
  lastModified?: string;
  userId?: string;
  ttl: number;
  url: string;
  method: string;
}

/**
 * Computer-use request body interface for type safety
 */
interface ComputerUseRequestBody {
  action?: string;
  [key: string]: unknown;
}

/**
 * Type guard for computer-use request body
 */
function isComputerUseRequestBody(
  body: unknown,
): body is ComputerUseRequestBody {
  return (
    typeof body === 'object' &&
    body !== null &&
    (typeof (body as Record<string, unknown>).action === 'string' ||
      (body as Record<string, unknown>).action === undefined)
  );
}

/**
 * Cached response data structure
 */
interface CachedResponse {
  data: unknown;
  metadata: CacheMetadata;
  headers: Record<string, string>;
}

/**
 * Cache statistics for monitoring
 */
interface CacheInterceptorStats {
  totalRequests: number;
  cacheHits: number;
  cacheMisses: number;
  cacheSkips: number;
  hitRate: number;
  averageResponseTime: number;
  endpointStats: Map<
    string,
    {
      hits: number;
      misses: number;
      hitRate: number;
    }
  >;
}

/**
 * Cache interceptor for API response caching
 */
@Injectable()
export class CacheInterceptor implements NestInterceptor {
  private readonly logger = new Logger(CacheInterceptor.name);
  private readonly stats: CacheInterceptorStats = {
    totalRequests: 0,
    cacheHits: 0,
    cacheMisses: 0,
    cacheSkips: 0,
    hitRate: 0,
    averageResponseTime: 0,
    endpointStats: new Map(),
  };

  // Default cache rules for different endpoint patterns
  private readonly cacheRules: CacheRule[] = [
    // Task data - cache for 5 minutes
    {
      pattern: /^\/api\/tasks\/[^/]+$/,
      ttl: 300,
      includeUserId: true,
      cacheableStatuses: [200],
      varyBy: ['Authorization'],
    },

    // Task lists - cache for 2 minutes
    {
      pattern: /^\/api\/tasks(\?.*)?$/,
      ttl: 120,
      includeUserId: true,
      cacheableStatuses: [200],
      varyBy: ['Authorization'],
      skipCacheIf: (req) => {
        // Skip cache if real-time data is requested
        return req.query.realtime === 'true';
      },
    },

    // Task messages - cache for 10 minutes
    {
      pattern: /^\/api\/tasks\/[^/]+\/messages/,
      ttl: 600,
      includeUserId: true,
      cacheableStatuses: [200],
      varyBy: ['Authorization'],
    },

    // Static data - cache for 1 hour
    {
      pattern: /^\/api\/models$/,
      ttl: 3600,
      cacheableStatuses: [200],
    },

    // Computer-use screenshots - cache for 30 seconds
    {
      pattern: /^\/computer-use$/,
      ttl: 30,
      cacheableStatuses: [200],
      skipCacheIf: (req) => {
        // Only cache screenshot requests - use type guard for safe access
        return (
          !isComputerUseRequestBody(req.body) ||
          req.body.action !== 'screenshot'
        );
      },
    },

    // Health checks - cache for 1 minute
    {
      pattern: /^\/health/,
      ttl: 60,
      cacheableStatuses: [200],
    },
  ];

  constructor(
    private readonly cacheService: CacheService,
    private readonly keyGenerator: CacheKeyGenerator,
    private readonly metricsService?: MetricsService,
  ) {
    this.logger.log('Cache Interceptor initialized');
    this.logger.log(`Configured ${this.cacheRules.length} cache rules`);

    // Start periodic stats reporting
    this.startPeriodicReporting();
  }

  /**
   * Intercept HTTP requests to implement caching
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<Request>();
    const response = context.switchToHttp().getResponse<Response>();

    // Only cache GET requests by default
    if (request.method !== 'GET') {
      // For non-GET requests, invalidate related cache entries
      this.invalidateRelatedCache(request);
      return next.handle();
    }

    const operationId =
      (request as Request & { operationId?: string }).operationId ||
      `cache_${Date.now()}`;
    const startTime = Date.now();

    // Find applicable cache rule
    const cacheRule = this.findCacheRule(request);
    if (!cacheRule) {
      this.stats.cacheSkips++;
      this.updateStats();
      return next.handle();
    }

    // Check if caching should be skipped
    if (cacheRule.skipCacheIf?.(request, response)) {
      this.stats.cacheSkips++;
      this.updateStats();
      return next.handle();
    }

    // Generate cache key
    const cacheKey = this.generateCacheKey(request, cacheRule);

    return this.handleCachedRequest(
      cacheKey,
      cacheRule,
      request,
      response,
      next,
      operationId,
      startTime,
    );
  }

  /**
   * Handle request with caching logic
   */
  private handleCachedRequest(
    cacheKey: string,
    cacheRule: CacheRule,
    request: Request,
    response: Response,
    next: CallHandler,
    operationId: string,
    startTime: number,
  ): Observable<unknown> {
    return new Observable((observer) => {
      // Try to get from cache first
      this.cacheService
        .get<CachedResponse>(cacheKey)
        .then((cachedResponse) => {
          if (cachedResponse && this.isCacheValid(cachedResponse, request)) {
            // Cache hit - return cached response
            this.handleCacheHit(
              cachedResponse,
              response,
              operationId,
              startTime,
            );
            observer.next(cachedResponse.data);
            observer.complete();
          } else {
            // Cache miss - execute request and cache result
            this.handleCacheMiss(
              cacheKey,
              cacheRule,
              request,
              response,
              next,
              operationId,
              startTime,
            ).subscribe({
              next: (data) => {
                observer.next(data);
              },
              error: (_error) => {
                observer.error(_error);
              },
              complete: () => {
                observer.complete();
              },
            });
          }
        })
        .catch((_error) => {
          // Cache error - proceed without cache
          this.logger.error(
            `[${operationId}] Cache retrieval error: ${_error instanceof Error ? _error.message : 'Unknown error'}`,
          );

          next.handle().subscribe({
            next: (data) => observer.next(data),
            error: (_error) => observer.error(_error),
            complete: () => observer.complete(),
          });
        });
    });
  }

  /**
   * Handle cache hit scenario
   */
  private handleCacheHit(
    cachedResponse: CachedResponse,
    response: Response,
    operationId: string,
    startTime: number,
  ): void {
    const duration = Date.now() - startTime;

    // Set cached headers
    Object.entries(cachedResponse.headers).forEach(([key, value]) => {
      response.set(key, value);
    });

    // Add cache headers
    response.set('X-Cache', 'HIT');
    response.set('X-Cache-Key', this.hashForLogging(operationId));

    this.stats.cacheHits++;
    this.recordEndpointStats(cachedResponse.metadata.url, 'hit');

    this.logger.debug(
      `[${operationId}] Cache HIT: ${cachedResponse.metadata.url} (${duration}ms)`,
      {
        cacheAge: Date.now() - cachedResponse.metadata.timestamp,
        ttl: cachedResponse.metadata.ttl,
      },
    );

    // Record metrics
    if (this.metricsService) {
      this.metricsService.recordCacheOperation?.('get', 'hit', duration);
    }

    this.updateStats();
  }

  /**
   * Handle cache miss scenario
   */
  private handleCacheMiss(
    cacheKey: string,
    cacheRule: CacheRule,
    request: Request,
    response: Response,
    next: CallHandler,
    operationId: string,
    startTime: number,
  ): Observable<unknown> {
    return next.handle().pipe(
      tap(async (data) => {
        const duration = Date.now() - startTime;

        this.stats.cacheMisses++;
        this.recordEndpointStats(request.url, 'miss');

        // Check if response should be cached
        if (this.shouldCacheResponse(response, cacheRule)) {
          // Create cached response
          const cachedResponse: CachedResponse = {
            data,
            metadata: {
              timestamp: Date.now(),
              etag: response.get('ETag'),
              lastModified: response.get('Last-Modified'),
              userId: this.extractUserId(request),
              ttl: cacheRule.ttl,
              url: request.url,
              method: request.method,
            },
            headers: this.extractCacheableHeaders(response),
          };

          // Store in cache
          await this.cacheService.set(cacheKey, cachedResponse, {
            ttl: cacheRule.ttl,
            namespace: 'api-cache',
          });

          this.logger.debug(
            `[${operationId}] Cache MISS: ${request.url} - stored for ${cacheRule.ttl}s (${duration}ms)`,
          );
        } else {
          this.logger.debug(
            `[${operationId}] Cache SKIP: ${request.url} - not cacheable (${duration}ms)`,
          );
        }

        // Add cache headers
        response.set('X-Cache', 'MISS');
        response.set('X-Cache-Key', this.hashForLogging(operationId));

        // Record metrics
        if (this.metricsService) {
          this.metricsService.recordCacheOperation?.('get', 'miss', duration);
        }

        this.updateStats();
      }),
    );
  }

  /**
   * Find applicable cache rule for request
   */
  private findCacheRule(request: Request): CacheRule | null {
    const path = request.url.split('?')[0]; // Remove query string for pattern matching

    for (const rule of this.cacheRules) {
      if (rule.pattern.test(path ?? '')) {
        return rule;
      }
    }

    return null;
  }

  /**
   * Generate cache key for request
   */
  private generateCacheKey(request: Request, cacheRule: CacheRule): string {
    const keyParts: string[] = [request.method, request.url];

    // Add user ID if required
    if (cacheRule.includeUserId) {
      const userId = this.extractUserId(request);
      if (userId) {
        keyParts.push(`user:${userId}`);
      }
    }

    // Add vary-by headers
    if (cacheRule.varyBy) {
      for (const header of cacheRule.varyBy) {
        const value = request.get(header);
        if (value) {
          keyParts.push(`${header}:${this.hashString(value)}`);
        }
      }
    }

    return this.keyGenerator.generateApiKey(
      request.method,
      request.url,
      request.query,
      cacheRule.includeUserId ? this.extractUserId(request) : undefined,
    );
  }

  /**
   * Check if cached response is still valid
   */
  private isCacheValid(
    cachedResponse: CachedResponse,
    request: Request,
  ): boolean {
    const now = Date.now();
    const cacheAge = (now - cachedResponse.metadata.timestamp) / 1000;

    // Check TTL expiration
    if (cacheAge > cachedResponse.metadata.ttl) {
      return false;
    }

    // Check ETag if provided in request
    const ifNoneMatch = request.get('If-None-Match');
    if (ifNoneMatch && cachedResponse.metadata.etag) {
      return ifNoneMatch === cachedResponse.metadata.etag;
    }

    // Check Last-Modified if provided in request
    const ifModifiedSince = request.get('If-Modified-Since');
    if (ifModifiedSince && cachedResponse.metadata.lastModified) {
      const modifiedSince = new Date(ifModifiedSince);
      const lastModified = new Date(cachedResponse.metadata.lastModified);
      return lastModified <= modifiedSince;
    }

    return true;
  }

  /**
   * Check if response should be cached
   */
  private shouldCacheResponse(
    response: Response,
    cacheRule: CacheRule,
  ): boolean {
    // Check status code
    if (
      cacheRule.cacheableStatuses &&
      !cacheRule.cacheableStatuses.includes(response.statusCode)
    ) {
      return false;
    }

    // Check for cache-control directives
    const cacheControl = response.get('Cache-Control');
    if (cacheControl) {
      if (
        cacheControl.includes('no-store') ||
        cacheControl.includes('private')
      ) {
        return false;
      }
    }

    return true;
  }

  /**
   * Extract user ID from request for user-specific caching
   */
  private extractUserId(request: Request): string | undefined {
    // Try to extract from various common locations
    const authHeader = request.get('Authorization');
    if (authHeader) {
      // Simple hash of auth header for user identification
      return this.hashString(authHeader).substring(0, 8);
    }

    // Try session or other user identification methods
    // This would be implemented based on the app's authentication strategy
    return undefined;
  }

  /**
   * Extract cacheable headers from response
   */
  private extractCacheableHeaders(response: Response): Record<string, string> {
    const cacheableHeaders = [
      'Content-Type',
      'ETag',
      'Last-Modified',
      'Expires',
      'Cache-Control',
    ];

    const headers: Record<string, string> = {};

    for (const header of cacheableHeaders) {
      const value = response.get(header);
      if (value) {
        headers[header] = value;
      }
    }

    return headers;
  }

  /**
   * Invalidate cache entries related to a mutation request
   */
  private async invalidateRelatedCache(request: Request): Promise<void> {
    try {
      // Extract resource pattern for invalidation
      const resourcePattern = this.extractResourcePattern(request);
      if (resourcePattern) {
        await this.cacheService.invalidatePattern(resourcePattern, 'api-cache');

        this.logger.debug(
          `Cache invalidation triggered by ${request.method} ${request.url}`,
          { pattern: resourcePattern },
        );
      }
    } catch (_error) {
      this.logger.error(
        `Cache invalidation _error: ${_error instanceof Error ? _error.message : 'Unknown _error'}`,
      );
    }
  }

  /**
   * Extract resource pattern for cache invalidation
   */
  private extractResourcePattern(request: Request): string | null {
    // Task operations - invalidate task-related cache
    if (request.url.match(/^\/api\/tasks/)) {
      const taskId = request.url.match(/\/api\/tasks\/([^/]+)/)?.[1];
      if (taskId) {
        return `api:*:tasks:${taskId}*`;
      } else {
        return 'api:*:tasks*';
      }
    }

    return null;
  }

  /**
   * Hash string for consistent identification
   */
  private hashString(input: string): string {
    return createHash('md5').update(input).digest('hex');
  }

  /**
   * Create safe hash for logging
   */
  private hashForLogging(input: string): string {
    return createHash('md5').update(input).digest('hex').substring(0, 8);
  }

  /**
   * Record endpoint-specific cache statistics
   */
  private recordEndpointStats(url: string, result: 'hit' | 'miss'): void {
    const normalizedUrl = this.normalizeUrlForStats(url);

    if (!this.stats.endpointStats.has(normalizedUrl)) {
      this.stats.endpointStats.set(normalizedUrl, {
        hits: 0,
        misses: 0,
        hitRate: 0,
      });
    }

    const endpointStats = this.stats.endpointStats.get(normalizedUrl)!;

    if (result === 'hit') {
      endpointStats.hits++;
    } else {
      endpointStats.misses++;
    }

    const total = endpointStats.hits + endpointStats.misses;
    endpointStats.hitRate = total > 0 ? (endpointStats.hits / total) * 100 : 0;
  }

  /**
   * Normalize URL for statistics grouping
   */
  private normalizeUrlForStats(url: string | undefined): string {
    if (!url) return '';
    return url
      .split('?')[0] // Remove query string
      .replace(/\/\d+/g, '/:id') // Replace IDs
      .replace(/\/[a-f0-9-]{36}/g, '/:uuid'); // Replace UUIDs
  }

  /**
   * Update overall cache statistics
   */
  private updateStats(): void {
    this.stats.totalRequests =
      this.stats.cacheHits + this.stats.cacheMisses + this.stats.cacheSkips;

    if (this.stats.totalRequests > 0) {
      this.stats.hitRate =
        (this.stats.cacheHits / this.stats.totalRequests) * 100;
    }
  }

  /**
   * Get current cache statistics
   */
  getStats(): CacheInterceptorStats {
    return {
      ...this.stats,
      endpointStats: new Map(this.stats.endpointStats),
    };
  }

  /**
   * Clear cache statistics
   */
  clearStats(): void {
    Object.assign(this.stats, {
      totalRequests: 0,
      cacheHits: 0,
      cacheMisses: 0,
      cacheSkips: 0,
      hitRate: 0,
      averageResponseTime: 0,
    });

    this.stats.endpointStats.clear();
    this.logger.log('Cache interceptor statistics cleared');
  }

  /**
   * Start periodic statistics reporting
   */
  private startPeriodicReporting(): void {
    // Report cache stats every 5 minutes
    setInterval(() => {
      if (this.stats.totalRequests > 0) {
        this.logger.log('Cache Interceptor Statistics:', {
          totalRequests: this.stats.totalRequests,
          cacheHits: this.stats.cacheHits,
          cacheMisses: this.stats.cacheMisses,
          cacheSkips: this.stats.cacheSkips,
          hitRate: `${this.stats.hitRate.toFixed(1)}%`,
          topEndpoints: Array.from(this.stats.endpointStats.entries())
            .sort((a, b) => b[1].hits + b[1].misses - (a[1].hits + a[1].misses))
            .slice(0, 5)
            .map(([url, stats]) => ({
              url,
              requests: stats.hits + stats.misses,
              hitRate: `${stats.hitRate.toFixed(1)}%`,
            })),
        });
      }
    }, 300000); // 5 minutes
  }
}

/**
 * Database Performance Interceptor - Query Monitoring and Optimization
 *
 * Provides comprehensive database query performance monitoring with
 * automatic slow query detection, query caching, and optimization
 * recommendations. Designed for enterprise database performance.
 *
 * Features:
 * - Database query performance tracking
 * - Slow query detection and alerting
 * - Query result caching with intelligent invalidation
 * - Database connection pool monitoring
 * - Query execution plan analysis
 * - Automatic retry logic for failed queries
 * - Comprehensive database metrics
 *
 * @author Claude Code - Performance Optimization Specialist
 * @version 1.0.0
 */


/* eslint-disable @typescript-eslint/no-unsafe-assignment */
/* eslint-disable @typescript-eslint/no-unsafe-argument */
/* eslint-disable @typescript-eslint/no-unsafe-member-access */




import {
  CallHandler,
  ExecutionContext,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, tap, catchError } from 'rxjs';
import { Request } from 'express';
import { MetricsService } from '../../metrics/metrics.service';
import { CacheService } from '../../cache/cache.service';
import { CacheKeyGenerator } from '../../cache/cache-key.generator';

/**
 * Database operation metadata
 */
interface DatabaseOperation {
  operation: string;
  table: string;
  query?: string;
  params?: Record<string, unknown>;
  executionPlan?: Record<string, unknown>;
}

/**
 * Database performance metrics for a single query
 */
interface DatabasePerformanceMetrics {
  operationId: string;
  operation: DatabaseOperation;
  startTime: number;
  endTime: number;
  duration: number;
  resultCount?: number;
  cacheHit?: boolean;
  connectionId?: string;
  error?: Error;
}

/**
 * Database performance statistics
 */
interface DatabaseStats {
  totalQueries: number;
  averageQueryTime: number;
  slowQueries: number;
  failedQueries: number;
  cacheHitRate: number;
  connectionPoolStats: {
    active: number;
    idle: number;
    total: number;
  };
  topSlowQueries: Array<{
    operation: string;
    table: string;
    avgDuration: number;
    count: number;
  }>;
}

/**
 * Database performance configuration
 */
interface DatabaseConfig {
  slowQueryThreshold: number; // milliseconds
  criticalQueryThreshold: number; // milliseconds
  enableQueryCaching: boolean;
  defaultCacheTtl: number; // seconds
  maxRetryAttempts: number;
  retryDelay: number; // milliseconds
}

/**
 * Database performance interceptor
 */
@Injectable()
export class DatabaseInterceptor implements NestInterceptor {
  private readonly logger = new Logger(DatabaseInterceptor.name);
  private readonly stats: DatabaseStats = {
    totalQueries: 0,
    averageQueryTime: 0,
    slowQueries: 0,
    failedQueries: 0,
    cacheHitRate: 0,
    connectionPoolStats: {
      active: 0,
      idle: 0,
      total: 0,
    },
    topSlowQueries: [],
  };

  private readonly slowQueries = new Map<
    string,
    {
      totalDuration: number;
      count: number;
      avgDuration: number;
    }
  >();

  // Database performance configuration
  private readonly config: DatabaseConfig = {
    slowQueryThreshold: parseInt(
      process.env.DB_SLOW_QUERY_THRESHOLD ?? '1000',
      10,
    ), // 1 second
    criticalQueryThreshold: parseInt(
      process.env.DB_CRITICAL_QUERY_THRESHOLD ?? '5000',
      10,
    ), // 5 seconds
    enableQueryCaching: process.env.DB_ENABLE_QUERY_CACHING !== 'false',
    defaultCacheTtl: parseInt(process.env.DB_CACHE_TTL ?? '300', 10), // 5 minutes
    maxRetryAttempts: parseInt(process.env.DB_MAX_RETRY_ATTEMPTS ?? '3', 10),
    retryDelay: parseInt(process.env.DB_RETRY_DELAY ?? '1000', 10), // 1 second
  };

  constructor(
    private readonly metricsService?: MetricsService,
    private readonly cacheService?: CacheService,
    private readonly keyGenerator?: CacheKeyGenerator,
  ) {
    this.logger.log('Database Performance Interceptor initialized');
    this.logger.log(
      `Config: slowQuery=${this.config.slowQueryThreshold}ms, caching=${this.config.enableQueryCaching}`,
    );

    // Start periodic reporting
    this.startPeriodicReporting();
  }

  /**
   * Intercept database operations for performance monitoring
   */
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();
    const operationId = request.operationId ?? `db_${Date.now()}`;

    // Extract database operation metadata
    const dbOperation = this.extractDatabaseOperation(context, request);
    if (!dbOperation) {
      return next.handle(); // Not a database operation
    }

    const startTime = Date.now();

    // Check cache first if caching is enabled
    if (
      this.config.enableQueryCaching &&
      this.isCacheableOperation(dbOperation)
    ) {
      return this.handleCachedDatabaseOperation(
        operationId,
        dbOperation,
        startTime,
        next,
      );
    }

    return this.handleDatabaseOperation(
      operationId,
      dbOperation,
      startTime,
      next,
    );
  }

  /**
   * Handle database operation with performance monitoring
   */
  private handleDatabaseOperation(
    operationId: string,
    dbOperation: DatabaseOperation,
    startTime: number,
    next: CallHandler,
  ): Observable<unknown> {
    this.logger.debug(
      `[${operationId}] Database operation: ${dbOperation.operation} on ${dbOperation.table}`,
    );

    return next.handle().pipe(
      tap((result) => {
        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          resultCount: this.getResultCount(result),
        });
      }),
      catchError((_error) => {
        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          error: _error,
        });
        throw _error;
      }),
    );
  }

  /**
   * Handle cached database operation
   */
  private handleCachedDatabaseOperation(
    operationId: string,
    dbOperation: DatabaseOperation,
    startTime: number,
    next: CallHandler,
  ): Observable<unknown> {
    if (!this.cacheService ?? !this.keyGenerator) {
      return this.handleDatabaseOperation(
        operationId,
        dbOperation,
        startTime,
        next,
      );
    }

    return new Observable((observer) => {
      const cacheKey = this.generateQueryCacheKey(dbOperation);

      this.cacheService!.get(cacheKey)
        .then((cachedResult) => {
          if (cachedResult !== null) {
            // Cache hit
            this.recordDatabaseMetrics({
              operationId,
              operation: dbOperation,
              startTime,
              endTime: Date.now(),
              duration: Date.now() - startTime,
              cacheHit: true,
              resultCount: this.getResultCount(cachedResult),
            });

            this.logger.debug(
              `[${operationId}] Database cache HIT: ${dbOperation.operation}`,
            );

            observer.next(cachedResult);
            observer.complete();
          } else {
            // Cache miss - execute query and cache result
            this.handleDatabaseOperationWithCaching(
              operationId,
              dbOperation,
              startTime,
              cacheKey,
              next,
            ).subscribe({
              next: (result) => observer.next(result),
              error: (_error) => observer.error(_error),
              complete: () => observer.complete(),
            });
          }
        })
        .catch((_error) => {
          this.logger.error(
            `[${operationId}] Cache error, falling back to database: ${_error.message}`,
          );

          this.handleDatabaseOperation(
            operationId,
            dbOperation,
            startTime,
            next,
          ).subscribe({
            next: (result) => observer.next(result),
            error: (_error) => observer.error(_error),
            complete: () => observer.complete(),
          });
        });
    });
  }

  /**
   * Handle database operation with result caching
   */
  private handleDatabaseOperationWithCaching(
    operationId: string,
    dbOperation: DatabaseOperation,
    startTime: number,
    cacheKey: string,
    next: CallHandler,
  ): Observable<unknown> {
    return next.handle().pipe(
      tap(async (result) => {
        const duration = Date.now() - startTime;

        // Cache the result
        if (this.cacheService) {
          await this.cacheService.set(cacheKey, result, {
            ttl: this.config.defaultCacheTtl,
            namespace: 'database-queries',
          });
        }

        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration,
          cacheHit: false,
          resultCount: this.getResultCount(result),
        });

        this.logger.debug(
          `[${operationId}] Database cache MISS: ${dbOperation.operation} - cached result (${duration}ms)`,
        );
      }),
      catchError((_error) => {
        this.recordDatabaseMetrics({
          operationId,
          operation: dbOperation,
          startTime,
          endTime: Date.now(),
          duration: Date.now() - startTime,
          error: _error,
        });
        throw _error;
      }),
    );
  }

  /**
   * Extract database operation from context
   */
  private extractDatabaseOperation(
    context: ExecutionContext,
    _request: Request,
  ): DatabaseOperation | null {
    // This would need to be customized based on the ORM/database library used
    // For Prisma, we might extract from the handler name or method metadata

    const handlerName = context.getHandler().name;
    const controllerClass = context.getClass().name;

    // Example patterns for different operations
    if (handlerName.includes('find') ?? handlerName.includes('get')) {
      return {
        operation: 'SELECT',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    if (handlerName.includes('create') ?? handlerName.includes('insert')) {
      return {
        operation: 'INSERT',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    if (handlerName.includes('update')) {
      return {
        operation: 'UPDATE',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    if (handlerName.includes('delete') ?? handlerName.includes('remove')) {
      return {
        operation: 'DELETE',
        table: this.extractTableName(controllerClass),
        query: `${handlerName} operation`,
      };
    }

    return null; // Not a database operation
  }

  /**
   * Extract table name from controller class name
   */
  private extractTableName(controllerClass: string): string {
    // Remove 'Controller' suffix and convert to lowercase
    return controllerClass
      .replace(/Controller$/i, '')
      .toLowerCase()
      .replace(/s$/, ''); // Remove plural 's' if present
  }

  /**
   * Check if operation is cacheable
   */
  private isCacheableOperation(dbOperation: DatabaseOperation): boolean {
    // Only cache read operations
    return ['SELECT', 'FIND', 'GET'].includes(
      dbOperation.operation.toUpperCase(),
    );
  }

  /**
   * Generate cache key for database query
   */
  private generateQueryCacheKey(dbOperation: DatabaseOperation): string {
    if (!this.keyGenerator) {
      return `db:${dbOperation.operation}:${dbOperation.table}:${Date.now()}`;
    }

    return this.keyGenerator.generateDbKey(
      dbOperation.table,
      dbOperation.operation,
      dbOperation.params,
    );
  }

  /**
   * Get result count from query result
   */
  private getResultCount(result: unknown): number | undefined {
    if (result === null ?? result === undefined) {
      return 0;
    }

    if (Array.isArray(result)) {
      return result.length;
    }

    if (typeof result === 'object' && result !== null && 'count' in result) {
      return (result as { count: number }).count;
    }

    return 1; // Single result
  }

  /**
   * Record database performance metrics
   */
  private recordDatabaseMetrics(metrics: DatabasePerformanceMetrics): void {
    try {
      const { operation, duration, error, cacheHit } = metrics;

      // Update internal statistics
      this.stats.totalQueries++;

      if (error) {
        this.stats.failedQueries++;
        this.logger.error(
          `[${metrics.operationId}] Database operation failed: ${error.message}`,
          { operation: operation.operation, table: operation.table, duration },
        );
      } else {
        // Update average query time
        this.stats.averageQueryTime =
          (this.stats.averageQueryTime * (this.stats.totalQueries - 1) +
            duration) /
          this.stats.totalQueries;

        // Check for slow queries
        if (duration >= this.config.slowQueryThreshold) {
          this.stats.slowQueries++;
          this.recordSlowQuery(operation, duration);

          const logLevel =
            duration >= this.config.criticalQueryThreshold ? 'error' : 'warn';
          this.logger[logLevel](
            `[${metrics.operationId}] Slow database query detected: ${duration}ms`,
            { operation: operation.operation, table: operation.table },
          );
        }

        this.logger.debug(
          `[${metrics.operationId}] Database operation completed: ${operation.operation} (${duration}ms)`,
          {
            table: operation.table,
            resultCount: metrics.resultCount,
            cacheHit: cacheHit ?? false,
          },
        );
      }

      // Record metrics with MetricsService
      if (this.metricsService) {
        if (error) {
          this.metricsService.recordDatabaseError(
            operation.operation,
            error.constructor.name,
          );
        } else {
          this.metricsService.recordDatabaseQuery(
            operation.operation,
            operation.table,
            duration,
          );
        }
      }

      // Update cache hit rate
      if (cacheHit !== undefined) {
        const totalCacheableQueries = this.stats.totalQueries; // Simplified
        const cacheHits = cacheHit ? 1 : 0;
        this.stats.cacheHitRate =
          (this.stats.cacheHitRate * (totalCacheableQueries - 1) +
            cacheHits * 100) /
          totalCacheableQueries;
      }
    } catch (_error) {
      this.logger.error(
        `Failed to record database metrics: ${_error instanceof Error ? _error.message : 'Unknown error'}`,
      );
    }
  }

  /**
   * Record slow query for analysis
   */
  private recordSlowQuery(
    operation: DatabaseOperation,
    duration: number,
  ): void {
    const queryKey = `${operation.operation}:${operation.table}`;

    if (!this.slowQueries.has(queryKey)) {
      this.slowQueries.set(queryKey, {
        totalDuration: duration,
        count: 1,
        avgDuration: duration,
      });
    } else {
      const slowQuery = this.slowQueries.get(queryKey)!;
      slowQuery.totalDuration += duration;
      slowQuery.count++;
      slowQuery.avgDuration = slowQuery.totalDuration / slowQuery.count;
    }

    // Update top slow queries
    this.updateTopSlowQueries();
  }

  /**
   * Update top slow queries list
   */
  private updateTopSlowQueries(): void {
    this.stats.topSlowQueries = Array.from(this.slowQueries.entries())
      .map(([key, stats]) => {
        const [operation, table] = key.split(':');
        return {
          operation,
          table,
          avgDuration: stats.avgDuration,
          count: stats.count,
        };
      })
      .sort((a, b) => b.avgDuration - a.avgDuration)
      .slice(0, 10); // Top 10 slow queries
  }

  /**
   * Get current database statistics
   */
  getStats(): DatabaseStats {
    this.updateTopSlowQueries();
    return { ...this.stats };
  }

  /**
   * Clear database statistics
   */
  clearStats(): void {
    Object.assign(this.stats, {
      totalQueries: 0,
      averageQueryTime: 0,
      slowQueries: 0,
      failedQueries: 0,
      cacheHitRate: 0,
      connectionPoolStats: {
        active: 0,
        idle: 0,
        total: 0,
      },
      topSlowQueries: [],
    });

    this.slowQueries.clear();
    this.logger.log('Database statistics cleared');
  }

  /**
   * Start periodic statistics reporting
   */
  private startPeriodicReporting(): void {
    // Report database stats every 10 minutes
    setInterval(() => {
      if (this.stats.totalQueries > 0) {
        this.logger.log('Database Performance Statistics:', {
          totalQueries: this.stats.totalQueries,
          averageQueryTime: `${this.stats.averageQueryTime.toFixed(2)}ms`,
          slowQueries: this.stats.slowQueries,
          failedQueries: this.stats.failedQueries,
          cacheHitRate: `${this.stats.cacheHitRate.toFixed(2)}%`,
          topSlowQueries: this.stats.topSlowQueries.slice(0, 3),
        });
      }
    }, 600000); // 10 minutes
  }
}

/**
 * Security Headers Middleware - Comprehensive HTTP Security Headers for BytebotD
 *
 * This middleware implements enterprise-grade security headers using helmet.js
 * with production-ready configurations for CSP, HSTS, CORS, and other security
 * headers. Includes environment-specific configurations and security monitoring.
 *
 * @fileoverview Enterprise security headers middleware for BytebotD service
 * @version 1.0.0
 * @author Security Headers & CORS Specialist
 */

import { Injectable, NestMiddleware, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import { SecurityEventType, createSecurityEvent } from '@bytebot/shared';

/**
 * Type-safe Express request with correlation ID
 */
interface SafeRequest extends Request {
  correlationId?: string;
}

/**
 * Type-safe helmet options interface
 */
interface SafeHelmetOptions {
  contentSecurityPolicy?:
    | {
        directives: Record<string, string[]>;
        reportOnly?: boolean;
      }
    | false;
  hsts?:
    | {
        maxAge: number;
        includeSubDomains: boolean;
        preload: boolean;
      }
    | false;
  frameguard?:
    | {
        action: 'deny' | 'sameorigin';
      }
    | false;
  noSniff?: boolean;
  xssFilter?: boolean;
  referrerPolicy?:
    | {
        policy: string;
      }
    | false;
  hidePoweredBy?: boolean;
  dnsPrefetchControl?: {
    allow: boolean;
  };
}

/**
 * Type-safe error with known properties
 */
interface SafeError extends Error {
  message: string;
  stack?: string;
}

/**
 * Security headers configuration interface
 */
interface SecurityMiddlewareConfig {
  /** Environment (development, staging, production) */
  environment: string;

  /** Enable Content Security Policy */
  csp: boolean;

  /** CSP directives */
  cspDirectives?: Record<string, string[]>;

  /** Enable HSTS */
  hsts: boolean;

  /** HSTS max age in seconds */
  hstsMaxAge: number;

  /** Include subdomains in HSTS */
  hstsIncludeSubDomains: boolean;

  /** Enable HSTS preload */
  hstsPreload: boolean;

  /** Frame options value */
  frameOptions: 'DENY' | 'SAMEORIGIN' | false;

  /** Enable X-Content-Type-Options: nosniff */
  noSniff: boolean;

  /** Enable X-XSS-Protection */
  xssFilter: boolean;

  /** Enable referrer policy */
  referrerPolicy: string | false;

  /** Allowed CORS origins */
  corsOrigins: string[] | string;

  /** CORS credentials */
  corsCredentials: boolean;

  /** Custom security headers */
  customHeaders?: Record<string, string>;

  /** Enable security event logging */
  enableSecurityLogging: boolean;

  /** Trusted proxies for IP detection */
  trustedProxies?: string[];
}

/**
 * Default security configurations by environment
 */
const SECURITY_CONFIGS: Record<string, Partial<SecurityMiddlewareConfig>> = {
  development: {
    csp: false, // Relaxed CSP for development
    hsts: false, // No HSTS in development
    frameOptions: 'SAMEORIGIN',
    corsOrigins: [
      'http://localhost:3000',
      'http://localhost:3001',
      'http://localhost:8080',
    ],
    corsCredentials: true,
    enableSecurityLogging: false,
  },

  staging: {
    csp: true,
    hsts: true,
    hstsMaxAge: 86400, // 1 day
    hstsIncludeSubDomains: true,
    hstsPreload: false,
    frameOptions: 'DENY',
    corsCredentials: true,
    enableSecurityLogging: true,
  },

  production: {
    csp: true,
    hsts: true,
    hstsMaxAge: 31536000, // 1 year
    hstsIncludeSubDomains: true,
    hstsPreload: true,
    frameOptions: 'DENY',
    corsCredentials: true,
    enableSecurityLogging: true,
    customHeaders: {
      'X-Powered-By': '', // Remove X-Powered-By header
      Server: '', // Remove Server header
      'X-Service': 'BytebotD',
      'X-API-Version': '1.0',
    },
  },
};

/**
 * Default CSP directives optimized for BytebotD desktop service
 */
const DEFAULT_CSP_DIRECTIVES = {
  'default-src': ["'self'"],
  'script-src': [
    "'self'",
    "'unsafe-inline'",
    "'unsafe-eval'",
    'https://cdn.jsdelivr.net',
  ],
  'style-src': ["'self'", "'unsafe-inline'", 'https://fonts.googleapis.com'],
  'font-src': ["'self'", 'https://fonts.gstatic.com', 'data:'],
  'img-src': ["'self'", 'data:', 'https:', 'blob:', 'http://localhost:*'],
  'media-src': ["'self'", 'blob:'],
  'object-src': ["'none'"],
  'base-uri': ["'self'"],
  'form-action': ["'self'"],
  'frame-ancestors': ["'self'", 'http://localhost:*'],
  'upgrade-insecure-requests': [],
  'connect-src': [
    "'self'",
    'ws:',
    'wss:',
    'http://localhost:*',
    'https://localhost:*',
  ],
};

@Injectable()
export class SecurityHeadersMiddleware implements NestMiddleware {
  private readonly logger = new Logger(SecurityHeadersMiddleware.name);
  private readonly config: SecurityMiddlewareConfig;
  private readonly helmetMiddleware: (
    _req: Request,
    res: Response,
    next: NextFunction,
  ) => void;

  constructor(private configService: ConfigService) {
    const environment =
      this.configService.get<string>('NODE_ENV') ?? 'development';
    const corsOrigins = this.configService.get<string[]>('CORS_ORIGINS') ?? [
      'http://localhost:3000',
      'http://localhost:8080',
    ];
    const securityHeaders =
      this.configService.get<Partial<SecurityMiddlewareConfig>>(
        'security.headers',
      ) ?? {};

    // Build configuration with type safety
    this.config = {
      environment,
      csp: true,
      hsts: environment === 'production',
      hstsMaxAge: environment === 'production' ? 31536000 : 86400,
      hstsIncludeSubDomains: true,
      hstsPreload: environment === 'production',
      frameOptions: 'SAMEORIGIN', // Allow framing for VNC viewer
      noSniff: true,
      xssFilter: true,
      referrerPolicy: 'same-origin',
      corsOrigins,
      corsCredentials: true,
      enableSecurityLogging: environment !== 'development',
      ...SECURITY_CONFIGS[environment],
      // Override with specific config values
      ...securityHeaders,
    };

    // Initialize helmet middleware
    this.helmetMiddleware = this.createHelmetMiddleware();

    this.logger.log('BytebotD security headers middleware initialized', {
      environment,
      csp: this.config.csp,
      hsts: this.config.hsts,
      frameOptions: this.config.frameOptions,
      corsOrigins: Array.isArray(this.config.corsOrigins)
        ? this.config.corsOrigins.length
        : 'wildcard',
      securityLogging: this.config.enableSecurityLogging,
    });
  }

  /**
   * Apply security headers to request
   */
  use(req: Request, res: Response, next: NextFunction): void {
    const operationId = `security-headers-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const startTime = Date.now();

    // Set correlation ID for request tracking with type safety
    const safeReq = req as SafeRequest;
    safeReq.correlationId = operationId;

    this.logger.debug(`[${operationId}] Applying BytebotD security headers`, {
      operationId,
      method: req.method,
      url: req.url,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
      origin: req.get('Origin'),
    });

    try {
      // Apply helmet security headers
      this.helmetMiddleware(req, res, (err?: Error | null) => {
        if (err) {
          const processingTime = Date.now() - startTime;
          const safeError = err as SafeError;

          this.logger.error(`[${operationId}] Helmet middleware error`, {
            operationId,
            error: safeError.message,
            stack: safeError.stack,
            processingTimeMs: processingTime,
          });

          // Log security event for middleware failure
          this.logSecurityEvent(
            req,
            'MIDDLEWARE_ERROR',
            safeError.message,
            operationId,
          );

          return next(err);
        }

        // Apply custom security headers
        this.applyCustomHeaders(res, operationId);

        // Apply CORS headers
        this.applyCorsHeaders(req, res, operationId);

        // Log successful application
        const processingTime = Date.now() - startTime;

        this.logger.debug(
          `[${operationId}] BytebotD security headers applied successfully`,
          {
            operationId,
            processingTimeMs: processingTime,
            headersCount: Object.keys(res.getHeaders()).length,
          },
        );

        next();
      });
    } catch (caughtError) {
      const processingTime = Date.now() - startTime;
      const safeError = caughtError as SafeError;

      this.logger.error(`[${operationId}] Security headers middleware error`, {
        operationId,
        error: safeError.message,
        stack: safeError.stack,
        processingTimeMs: processingTime,
      });

      // Log security event
      this.logSecurityEvent(
        req,
        'MIDDLEWARE_FAILURE',
        safeError.message,
        operationId,
      );

      next(caughtError);
    }
  }

  /**
   * Create helmet middleware with BytebotD-specific configuration
   */
  private createHelmetMiddleware(): (
    req: Request,
    res: Response,
    next: NextFunction,
  ) => void {
    const helmetOptions: SafeHelmetOptions = {
      // Content Security Policy optimized for desktop service
      contentSecurityPolicy: this.config.csp
        ? {
            directives: {
              ...DEFAULT_CSP_DIRECTIVES,
              ...this.config.cspDirectives,
            },
            reportOnly: this.config.environment === 'development',
          }
        : false,

      // HTTP Strict Transport Security
      hsts: this.config.hsts
        ? {
            maxAge: this.config.hstsMaxAge,
            includeSubDomains: this.config.hstsIncludeSubDomains,
            preload: this.config.hstsPreload,
          }
        : false,

      // X-Frame-Options - Allow framing for VNC viewer
      frameguard: this.config.frameOptions
        ? {
            action: this.config.frameOptions.toLowerCase() as
              | 'deny'
              | 'sameorigin',
          }
        : false,

      // X-Content-Type-Options
      noSniff: this.config.noSniff,

      // X-XSS-Protection
      xssFilter: this.config.xssFilter,

      // Referrer Policy
      referrerPolicy: this.config.referrerPolicy
        ? {
            policy: this.config.referrerPolicy as
              | 'same-origin'
              | 'strict-origin'
              | 'strict-origin-when-cross-origin'
              | 'no-referrer'
              | 'no-referrer-when-downgrade'
              | 'origin'
              | 'origin-when-cross-origin'
              | 'unsafe-url',
          }
        : false,

      // Hide X-Powered-By
      hidePoweredBy: true,

      // DNS Prefetch Control
      dnsPrefetchControl: {
        allow: false,
      },

      // Note: Expect-CT has been deprecated and removed from helmet v8.1.0
      // CT (Certificate Transparency) is now handled by browsers automatically

      // Note: Permissions Policy is not directly supported by helmet v8.1.0
      // It should be configured separately if needed via custom middleware
    };

    return helmet(helmetOptions);
  }

  /**
   * Apply custom security headers for BytebotD
   */
  private applyCustomHeaders(res: Response, operationId: string): void {
    if (!this.config.customHeaders) {
      return;
    }

    let headersApplied = 0;

    for (const [header, value] of Object.entries(this.config.customHeaders)) {
      if (value === '') {
        // Remove header
        res.removeHeader(header);
      } else {
        // Set header
        res.setHeader(header, value);
      }
      headersApplied++;
    }

    this.logger.debug(
      `[${operationId}] Applied custom BytebotD security headers`,
      {
        operationId,
        headersApplied,
        headers: Object.keys(this.config.customHeaders),
      },
    );
  }

  /**
   * Apply CORS headers with BytebotD-specific origins
   */
  private applyCorsHeaders(
    req: Request,
    res: Response,
    operationId: string,
  ): void {
    const origin = req.get('Origin');

    if (!origin) {
      return; // No CORS needed for same-origin requests
    }

    // Check if origin is allowed
    const isAllowedOrigin = this.isOriginAllowed(origin);

    if (isAllowedOrigin) {
      res.setHeader('Access-Control-Allow-Origin', origin);

      if (this.config.corsCredentials) {
        res.setHeader('Access-Control-Allow-Credentials', 'true');
      }

      // Set other CORS headers for preflight
      if (req.method === 'OPTIONS') {
        res.setHeader(
          'Access-Control-Allow-Methods',
          'GET, POST, PUT, DELETE, PATCH, OPTIONS',
        );
        res.setHeader(
          'Access-Control-Allow-Headers',
          'Origin, X-Requested-With, Content-Type, Accept, Authorization, X-API-Key, X-Service-ID',
        );
        res.setHeader('Access-Control-Max-Age', '86400'); // 24 hours
      }

      this.logger.debug(`[${operationId}] BytebotD CORS headers applied`, {
        operationId,
        origin,
        credentials: this.config.corsCredentials,
        method: req.method,
        isPreflight: req.method === 'OPTIONS',
      });
    } else {
      // Log potential security issue
      this.logger.warn(
        `[${operationId}] CORS blocked for unauthorized origin`,
        {
          operationId,
          origin,
          method: req.method,
          url: req.url,
          ip: req.ip,
        },
      );

      this.logSecurityEvent(
        req,
        'CORS_VIOLATION',
        `Unauthorized origin: ${origin}`,
        operationId,
      );
    }
  }

  /**
   * Check if origin is allowed by CORS policy
   */
  private isOriginAllowed(origin: string): boolean {
    if (typeof this.config.corsOrigins === 'string') {
      return (
        this.config.corsOrigins === '*' ?? this.config.corsOrigins === origin
      );
    }

    if (Array.isArray(this.config.corsOrigins)) {
      return (
        this.config.corsOrigins.includes(origin) ||
        this.config.corsOrigins.includes('*') ||
        this.config.corsOrigins.some((allowed) => {
          // Support wildcard subdomains
          if (allowed.startsWith('*.')) {
            const domain = allowed.substring(2);
            return origin.endsWith(domain);
          }
          // Support localhost with any port
          if (allowed.includes('localhost:*')) {
            const baseOrigin = allowed.replace(':*', '');
            return origin.startsWith(baseOrigin);
          }
          return allowed === origin;
        })
      );
    }

    return false;
  }

  /**
   * Log security events for audit purposes
   */
  private logSecurityEvent(
    req: Request,
    eventType: string,
    message: string,
    operationId: string,
  ): void {
    if (!this.config.enableSecurityLogging) {
      return;
    }

    try {
      const securityEventType = this.mapEventType(eventType);

      const securityEvent = createSecurityEvent(
        securityEventType,
        req.url,
        req.method,
        false,
        message,
        {
          operationId,
          middleware: 'security-headers',
          service: 'BytebotD',
          eventType,
          userAgent: req.get('User-Agent'),
          origin: req.get('Origin'),
          referer: req.get('Referer'),
        },
        undefined, // No user ID at middleware level
        req.ip,
        req.get('User-Agent'),
      );

      this.logger.warn(
        `BytebotD security headers event: ${securityEvent.eventId}`,
        {
          eventId: securityEvent.eventId,
          eventType: securityEvent.type,
          riskScore: securityEvent.riskScore,
          operationId,
        },
      );
    } catch (caughtError) {
      const safeError = caughtError as SafeError;
      this.logger.error('Failed to log BytebotD security headers event', {
        operationId,
        error: safeError.message,
        originalEventType: eventType,
      });
    }
  }

  /**
   * Map internal event types to security event types
   */
  private mapEventType(eventType: string): SecurityEventType {
    switch (eventType) {
      case 'CORS_VIOLATION':
        return SecurityEventType._ACCESS_DENIED;
      case 'MIDDLEWARE_ERROR':
      case 'MIDDLEWARE_FAILURE':
        return SecurityEventType._SECURITY_CONFIG_CHANGED;
      default:
        return SecurityEventType._SUSPICIOUS_ACTIVITY;
    }
  }

  /**
   * Get current security configuration (for debugging)
   */
  getSecurityConfig(): SecurityMiddlewareConfig {
    return { ...this.config };
  }

  /**
   * Validate security headers on response (for testing)
   */
  validateSecurityHeaders(headers: Record<string, string>): {
    valid: boolean;
    missing: string[];
    recommendations: string[];
  } {
    const missing: string[] = [];
    const recommendations: string[] = [];

    // Check for essential security headers
    const essentialHeaders = [
      'x-content-type-options',
      'x-frame-options',
      'x-xss-protection',
      'referrer-policy',
    ];

    essentialHeaders.forEach((header) => {
      if (!headers[header]) {
        missing.push(header);
      }
    });

    // Check for HSTS in production
    if (
      this.config.environment === 'production' &&
      !headers['strict-transport-security']
    ) {
      missing.push('strict-transport-security');
      recommendations.push('Enable HSTS for production environment');
    }

    // Check for CSP
    if (this.config.csp && !headers['content-security-policy']) {
      missing.push('content-security-policy');
      recommendations.push('Content Security Policy should be configured');
    }

    return {
      valid: missing.length === 0,
      missing,
      recommendations,
    };
  }
}

export default SecurityHeadersMiddleware;

/**
 * Global Validation Pipe - Enterprise Security Input Validation for BytebotD
 *
 * This pipe provides comprehensive input validation and sanitization for all API endpoints
 * in the BytebotD desktop service. Features include XSS protection, SQL injection prevention,
 * request size limits, and structured error reporting for security audit trails.
 *
 * @fileoverview Enterprise-grade validation pipe for BytebotD API security
 * @version 1.0.0
 * @author Input Validation & API Security Specialist
 */

import {
  PipeTransform,
  Injectable,
  ArgumentMetadata,
  BadRequestException,
  Logger,
  PayloadTooLargeException,
} from '@nestjs/common';
import { validate, ValidationError } from 'class-validator';
import { plainToClass } from 'class-transformer';
import {
  sanitizeInput,
  sanitizeObject,
  detectXSS,
  detectSQLInjection,
  createSecurityEvent,
  SecurityEventType,
  DEFAULT_SANITIZATION_OPTIONS,
  SanitizationOptions,
} from '@bytebot/shared';

/**
 * Configuration options for the global validation pipe
 */
interface GlobalValidationPipeOptions {
  /** Transform input to target class instance */
  transform?: boolean;

  /** Strip properties not defined in DTO class */
  whitelist?: boolean;

  /** Throw error if non-whitelisted properties exist */
  forbidNonWhitelisted?: boolean;

  /** Enable input sanitization */
  enableSanitization?: boolean;

  /** Custom sanitization options */
  sanitizationOptions?: SanitizationOptions;

  /** Maximum request payload size in bytes */
  maxPayloadSize?: number;

  /** Enable security threat detection */
  enableThreatDetection?: boolean;

  /** Skip validation for certain metadata types */
  skipMissingProperties?: boolean;
}

/**
 * Default validation pipe options for BytebotD
 */
const DEFAULT_OPTIONS: GlobalValidationPipeOptions = {
  transform: true,
  whitelist: true,
  forbidNonWhitelisted: true,
  enableSanitization: true,
  sanitizationOptions: {
    ...DEFAULT_SANITIZATION_OPTIONS,
    // Allow slightly more flexible content for desktop operations
    maxLength: 100000, // 100KB for large desktop data
  },
  maxPayloadSize: 100 * 1024 * 1024, // 100MB for screenshots and large payloads
  enableThreatDetection: true,
  skipMissingProperties: false,
};

@Injectable()
export class GlobalValidationPipe implements PipeTransform<unknown> {
  private readonly logger = new Logger(GlobalValidationPipe.name);
  private readonly options: GlobalValidationPipeOptions;

  constructor(options?: Partial<GlobalValidationPipeOptions>) {
    this.options = { ...DEFAULT_OPTIONS, ...options };

    this.logger.log('BytebotD global validation pipe initialized', {
      enableSanitization: this.options.enableSanitization,
      enableThreatDetection: this.options.enableThreatDetection,
      maxPayloadSize: this.options.maxPayloadSize,
      whitelist: this.options.whitelist,
      forbidNonWhitelisted: this.options.forbidNonWhitelisted,
    });
  }

  /**
   * Transform and validate incoming data
   * @param value - Raw input value
   * @param metadata - Argument metadata from NestJS
   * @returns Validated and transformed value
   */
  async transform(
    value: unknown,
    metadata: ArgumentMetadata,
  ): Promise<unknown> {
    const operationId = `validation-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const startTime = Date.now();

    this.logger.debug(`[${operationId}] Starting BytebotD validation`, {
      operationId,
      type: metadata.type,
      metatype: metadata.metatype?.name,
      hasValue: value !== undefined && value !== null,
      valueType: typeof value,
    });

    try {
      // Skip validation for primitive types or when no metatype is provided
      if (!metadata.metatype ?? this.isBasicType(metadata.metatype)) {
        this.logger.debug(
          `[${operationId}] Skipping validation for basic type`,
          {
            operationId,
            type: metadata.type,
            metatype: metadata.metatype?.name,
          },
        );
        return this.sanitizeBasicValue(value, operationId);
      }

      // Check payload size if it's an object
      if (typeof value === 'object' && value !== null) {
        this.validatePayloadSize(value, operationId);
      }

      // Perform security threat detection
      if (this.options.enableThreatDetection) {
        this.detectSecurityThreats(value, operationId);
      }

      // Sanitize input if enabled
      let sanitizedValue = value;
      if (this.options.enableSanitization) {
        sanitizedValue = this.sanitizeValue(value, operationId);
      }

      // Transform to class instance
      const transformedValue = this.options.transform
        ? plainToClass(metadata.metatype, sanitizedValue)
        : sanitizedValue;

      // Perform class-validator validation
      if (this.shouldValidate(metadata)) {
        await this.validateValue(
          transformedValue,
          metadata.metatype,
          operationId,
        );
      }

      const processingTime = Date.now() - startTime;

      this.logger.debug(
        `[${operationId}] BytebotD validation completed successfully`,
        {
          operationId,
          type: metadata.type,
          metatype: metadata.metatype?.name,
          processingTimeMs: processingTime,
          sanitized: this.options.enableSanitization,
          threatDetected: false,
        },
      );

      return transformedValue;
    } catch (error) {
      const processingTime = Date.now() - startTime;

      this.logger.error(`[${operationId}] BytebotD validation failed`, {
        operationId,
        type: metadata.type,
        metatype: metadata.metatype?.name,
        error: (error as Error).message,
        processingTimeMs: processingTime,
      });

      // Log security event for validation failures
      this.logSecurityEvent(operationId, error, value, metadata);

      throw error;
    }
  }

  /**
   * Check if the metatype is a basic JavaScript type
   * @param metatype - The metatype to check
   * @returns True if it's a basic type
   */
  private isBasicType(metatype: unknown): boolean {
    const basicTypes = [String, Boolean, Number, Array, Object];
    return basicTypes.includes(metatype);
  }

  /**
   * Sanitize basic value (string, number, etc.)
   * @param value - Value to sanitize
   * @param operationId - Operation tracking ID
   * @returns Sanitized value
   */
  private sanitizeBasicValue(value: unknown, operationId: string): unknown {
    if (typeof value === 'string' && this.options.enableSanitization) {
      const sanitized = sanitizeInput(value, this.options.sanitizationOptions);

      if (sanitized !== value) {
        this.logger.debug(`[${operationId}] Basic value sanitized`, {
          operationId,
          originalLength: value.length,
          sanitizedLength: sanitized.length,
          changed: true,
        });
      }

      return sanitized;
    }

    return value;
  }

  /**
   * Validate payload size against limits
   * @param value - Value to check size for
   * @param operationId - Operation tracking ID
   */
  private validatePayloadSize(value: unknown, operationId: string): void {
    try {
      const payloadSize = JSON.stringify(value).length;

      if (payloadSize > this.options.maxPayloadSize!) {
        this.logger.warn(`[${operationId}] Payload size limit exceeded`, {
          operationId,
          payloadSize,
          maxPayloadSize: this.options.maxPayloadSize,
          ratio: (payloadSize / this.options.maxPayloadSize!).toFixed(2),
        });

        throw new PayloadTooLargeException(
          `Request _payload too large. Maximum allowed: ${this.options.maxPayloadSize} bytes`,
        );
      }

      this.logger.debug(`[${operationId}] Payload size validation passed`, {
        operationId,
        payloadSize,
        maxPayloadSize: this.options.maxPayloadSize,
        utilizationPercent: (
          (payloadSize / this.options.maxPayloadSize!) *
          100
        ).toFixed(1),
      });
    } catch (error) {
      if (error instanceof PayloadTooLargeException) {
        throw error;
      }

      // If we can't stringify the value, it might be too large or contain circular references
      this.logger.warn(`[${operationId}] Could not validate _payload size`, {
        operationId,
        error: (error as Error).message,
      });
    }
  }

  /**
   * Detect potential security threats in the input
   * @param value - Value to analyze
   * @param operationId - Operation tracking ID
   */
  private detectSecurityThreats(value: unknown, operationId: string): void {
    const threats: string[] = [];

    // Convert value to string for pattern analysis
    const stringValue =
      typeof value === 'string' ? value : JSON.stringify(value);

    // Detect XSS attempts
    if (detectXSS(stringValue)) {
      threats.push('XSS');

      this.logger.warn(`[${operationId}] XSS attempt detected`, {
        operationId,
        threatType: 'XSS',
        inputLength: stringValue.length,
        inputPreview: stringValue.substring(0, 100) + '...',
      });
    }

    // Detect SQL injection attempts
    if (detectSQLInjection(stringValue)) {
      threats.push('SQL_INJECTION');

      this.logger.warn(`[${operationId}] SQL injection attempt detected`, {
        operationId,
        threatType: 'SQL_INJECTION',
        inputLength: stringValue.length,
        inputPreview: stringValue.substring(0, 100) + '...',
      });
    }

    // Throw error if threats detected
    if (threats.length > 0) {
      const threatTypes = threats.join(', ');

      this.logger.error(`[${operationId}] Security threats blocked`, {
        operationId,
        threatTypes: threatTypes,
        threatCount: threats.length,
        blocked: true,
      });

      throw new BadRequestException(
        `Security violation detected: ${threatTypes}. Request has been blocked and logged.`,
      );
    }
  }

  /**
   * Sanitize input value based on type
   * @param value - Value to sanitize
   * @param operationId - Operation tracking ID
   * @returns Sanitized value
   */
  private sanitizeValue(value: unknown, operationId: string): unknown {
    const startTime = Date.now();
    let sanitized: unknown;

    if (typeof value === 'string') {
      sanitized = sanitizeInput(value, this.options.sanitizationOptions);
    } else if (typeof value === 'object' && value !== null) {
      sanitized = sanitizeObject(value, this.options.sanitizationOptions);
    } else {
      sanitized = value;
    }

    const sanitizationTime = Date.now() - startTime;
    const hasChanges = JSON.stringify(sanitized) !== JSON.stringify(value);

    this.logger.debug(
      `[${operationId}] BytebotD input sanitization completed`,
      {
        operationId,
        inputType: typeof value,
        isObject: typeof value === 'object',
        sanitizationTimeMs: sanitizationTime,
        hasChanges,
        originalSize: JSON.stringify(value).length,
        sanitizedSize: JSON.stringify(sanitized).length,
      },
    );

    return sanitized;
  }

  /**
   * Check if validation should be performed for the given metadata
   * @param metadata - Argument metadata
   * @returns True if validation should be performed
   */
  private shouldValidate(metadata: ArgumentMetadata): boolean {
    const { type, metatype } = metadata;

    // Skip validation for certain types
    if (type === 'custom' ?? !metatype) {
      return false;
    }

    return true;
  }

  /**
   * Perform class-validator validation
   * @param value - Value to validate
   * @param metatype - Target class type
   * @param operationId - Operation tracking ID
   */
  private async validateValue(
    value: unknown,
    metatype: unknown,
    operationId: string,
  ): Promise<void> {
    const startTime = Date.now();

    const errors: ValidationError[] = await validate(value, {
      whitelist: this.options.whitelist,
      forbidNonWhitelisted: this.options.forbidNonWhitelisted,
      skipMissingProperties: this.options.skipMissingProperties,
    });

    const validationTime = Date.now() - startTime;

    if (errors.length > 0) {
      const formattedErrors = this.formatValidationErrors(errors);

      this.logger.warn(`[${operationId}] BytebotD class validation failed`, {
        operationId,
        metatype: metatype.name,
        errorCount: errors.length,
        validationTimeMs: validationTime,
        errors: formattedErrors,
      });

      throw new BadRequestException({
        message: 'Validation failed',
        errors: formattedErrors,
        timestamp: new Date().toISOString(),
        operationId,
        service: 'BytebotD',
      });
    }

    this.logger.debug(`[${operationId}] BytebotD class validation passed`, {
      operationId,
      metatype: metatype.name,
      validationTimeMs: validationTime,
      errorCount: 0,
    });
  }

  /**
   * Format validation errors for consistent response structure
   * @param errors - Class-validator errors
   * @returns Formatted error array
   */
  private formatValidationErrors(errors: ValidationError[]): unknown[] {
    return errors.map((error) => ({
      property: error.property,
      value: error.value,
      constraints: error.constraints,
      children:
        error.children?.length > 0
          ? this.formatValidationErrors(error.children)
          : undefined,
    }));
  }

  /**
   * Log security event for audit trail
   * @param operationId - Operation tracking ID
   * @param error - Error that occurred
   * @param value - Original input value
   * @param metadata - Argument metadata
   */
  private logSecurityEvent(
    operationId: string,
    error: unknown,
    value: unknown,
    metadata: ArgumentMetadata,
  ): void {
    try {
      let eventType = SecurityEventType._VALIDATION_FAILED;

      if (error.message?.includes('XSS')) {
        eventType = SecurityEventType._XSS_ATTEMPT_BLOCKED;
      } else if (error.message?.includes('SQL')) {
        eventType = SecurityEventType._INJECTION_ATTEMPT_BLOCKED;
      }

      const securityEvent = createSecurityEvent(
        eventType,
        `validation-pipe-${metadata.type}`,
        'POST',
        false,
        error.message ?? 'Validation failed',
        {
          operationId,
          service: 'BytebotD',
          inputType: typeof value,
          metatype: metadata.metatype?.name,
          errorType: error.constructor.name,
          threatDetection: this.options.enableThreatDetection,
          sanitizationEnabled: this.options.enableSanitization,
        },
      );

      this.logger.warn(
        `BytebotD security event logged: ${securityEvent.eventId}`,
        {
          eventId: securityEvent.eventId,
          eventType: securityEvent.type,
          riskScore: securityEvent.riskScore,
          operationId,
        },
      );
    } catch (loggingError) {
      this.logger.error('Failed to log BytebotD security event', {
        operationId,
        originalError: loggingError.message,
        loggingError:
          loggingError instanceof Error
            ? loggingError.message
            : String(loggingError),
      });
    }
  }
}

/**
 * Factory function to create validation pipe with custom options
 * @param options - Custom validation pipe options
 * @returns Configured validation pipe instance
 */
export function createBytebotDValidationPipe(
  options?: Partial<GlobalValidationPipeOptions>,
