        action: 'write_file',
        path: '/home/user/test.txt',
        data: 'invalid-base64',
      };

      const result = (await service.action(action)) as FileWriteResult;

      expect(result.success).toBe(false);
      expect(result.message).toContain('Invalid base64 data');
    });
  });
