  y: number;
  button: number;
  clicks: number;
  altKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
}

interface UiohookKeyboardEvent {
  type: number;
  time: number;
  keycode: number;
  altKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
}

interface UiohookWheelEvent {
  type: number;
  time: number;
  x: number;
  y: number;
  clicks?: number;
  amount?: number;
  direction: number;
  rotation: number;
  altKey?: boolean;
  ctrlKey?: boolean;
  metaKey?: boolean;
  shiftKey?: boolean;
}

enum EventType {
  EVENT_MOUSE_CLICKED = 1,
  EVENT_MOUSE_PRESSED = 2,
  EVENT_MOUSE_RELEASED = 3,
