/**
 * Security Configuration Deployment - BytebotD Service
 *
 * This module provides the standardized security middleware deployment configuration
 * for BytebotD (Computer Control Service) with MAXIMUM SECURITY settings.
 *
 * @fileoverview BytebotD security middleware deployment configuration
 * @version 1.0.0
 * @author Security Configuration Deployment Specialist
 */

import {
  Injectable,
  MiddlewareConsumer,
  Module,
  NestModule,
} from '@nestjs/common';
import { ConfigModule, ConfigService } from '@nestjs/config';
import {
  StandardizedSecurityMiddleware,
  ServiceType,
  StandardizedValidationPipe,
  StandardizedRateLimitGuard,
  StandardizedValidationPipes,
} from '@bytebot/shared/dist/index-server';

/**
 * BytebotD Security Configuration Service
 * Provides MAXIMUM SECURITY configuration for computer control operations
 */
@Injectable()
export class BytebotDSecurityConfigService {
  constructor(private configService: ConfigService) {}

  /**
   * Create BytebotD security middleware with maximum security settings
   */
  createSecurityMiddleware(): StandardizedSecurityMiddleware {
    return StandardizedSecurityMiddleware.createBytebotDMiddleware(
      this.configService,
    );
  }

  /**
   * Create BytebotD validation pipe with maximum security settings
   */
  createValidationPipe(): StandardizedValidationPipe {
    const environment = this.configService.get<string>(
      'NODE_ENV',
      'development',
    );

    // Use maximum security pipe for BytebotD
    return StandardizedValidationPipes.MAXIMUM_SECURITY(environment);
  }

  /**
   * Create BytebotD rate limit guard with strict rate limits
   */
  createRateLimitGuard(
    _reflector: any,
    _redisClient?: any,
  ): StandardizedRateLimitGuard {
    return StandardizedRateLimitGuard.createBytebotDGuard(
      this.configService.get('NODE_ENV', 'development'),
      {
        // Additional configuration can be added here if needed
      },
    );
  }

  /**
   * Get security configuration for manual inspection
   */
  getSecurityConfig() {
    const environment = this.configService.get<string>(
      'NODE_ENV',
      'development',
    );

    return {
      serviceType: ServiceType._BYTEBOTD,
      environment,
      securityLevel: 'MAXIMUM',
      description: 'Computer Control Service - Maximum Security Configuration',
      middleware: {
        enabled: true,
        csp: environment === 'production',
        hsts: environment === 'production',
        frameOptions: 'SAMEORIGIN', // Allow VNC embedding
        corsOrigins:
          environment === 'production'
            ? ['https://app.bytebot.ai', 'https://bytebot.ai']
            : [
                'http://localhost:3000',
                'http://localhost:3001',
                'http://localhost:8080',
              ],
      },
      validation: {
        enableSanitization: true,
        enableThreatDetection: true,
        maxPayloadSize: '50mb',
        securityLevel: 'MAXIMUM',
      },
      rateLimiting: {
        authRequests: 3, // Very strict for computer control
        computerOperations: 50,
        taskOperations: 20,
        readOperations: 100,
        websocketConnections: 5,
      },
      features: {
        vnc: true, // BytebotD supports VNC
        computerControl: true,
        taskExecution: true,
        securityLogging: environment !== 'development',
      },
    };
  }
}

/**
 * BytebotD Security Configuration Module
 * Provides all security components for BytebotD service
 */
@Module({
  imports: [ConfigModule],
  providers: [
    BytebotDSecurityConfigService,
    {
      provide: 'BYTEBOT_D_SECURITY_MIDDLEWARE',
      useFactory: (configService: ConfigService) =>
        StandardizedSecurityMiddleware.createBytebotDMiddleware(configService),
      inject: [ConfigService],
    },
    {
      provide: 'BYTEBOT_D_VALIDATION_PIPE',
      useFactory: (configService: ConfigService) => {
        const environment = configService.get('NODE_ENV', 'development');
        return StandardizedValidationPipes.MAXIMUM_SECURITY(environment);
      },
      inject: [ConfigService],
    },
  ],
  exports: [
    BytebotDSecurityConfigService,
    'BYTEBOT_D_SECURITY_MIDDLEWARE',
    'BYTEBOT_D_VALIDATION_PIPE',
  ],
})
export class BytebotDSecurityModule implements NestModule {
  constructor(private configService: ConfigService) {}

  configure(consumer: MiddlewareConsumer) {
    // Apply BytebotD security middleware to all routes
    const securityMiddleware =
      StandardizedSecurityMiddleware.createBytebotDMiddleware(
        this.configService,
      );

    consumer
      .apply(securityMiddleware.use.bind(securityMiddleware))
      .forRoutes('*');
  }
}

/**
 * BytebotD Security Deployment Helper
 * Utility functions for deploying BytebotD security configuration
 */
export class BytebotDSecurityDeployment {
  /**
   * Apply BytebotD security to NestJS application
   * @param app - NestJS application instance
   * @param configService - Configuration service
   */
  static async applySecurityToApp(app: any, configService: ConfigService) {
    const environment = configService.get('NODE_ENV', 'development');

    // Apply global validation pipe with maximum security
    app.useGlobalPipes(
      StandardizedValidationPipes.MAXIMUM_SECURITY(environment),
    );

    // Log security deployment
    const _logger = app.get('Logger');
    if (_logger) {
      _logger.log('BytebotD security middleware deployed successfully', {
        service: 'BytebotD',
        securityLevel: 'MAXIMUM',
        environment,
        features: {
          vnc: true,
          computerControl: true,
          maximumSecurity: true,
        },
      });
    }
  }

  /**
   * Get security headers for BytebotD
   */
  static getSecurityHeaders(environment: string) {
    const isProd = environment === 'production';

    return {
      'X-Service': 'BytebotD',
      'X-Security-Level': 'MAXIMUM',
      'X-Computer-Control': 'true',
      'X-VNC-Enabled': 'true',
      'X-Frame-Options': 'SAMEORIGIN', // Allow VNC embedding
      ...(isProd && {
        'Strict-Transport-Security':
          'max-age=31536000; includeSubDomains; preload',
        'X-Content-Type-Options': 'nosniff',
        'X-XSS-Protection': '1; mode=block',
        'Referrer-Policy': 'same-origin',
      }),
    };
  }

  /**
   * Validate BytebotD security configuration
   */
  static validateSecurityConfig(configService: ConfigService) {
    const environment = configService.get('NODE_ENV', 'development');
    const corsOrigins = configService.get('CORS_ORIGINS', []);

    const validationResults = {
      environment,
      valid: true,
      warnings: [] as string[],
      errors: [] as string[],
    };

    // Check CORS configuration
    if (environment === 'production' && corsOrigins.includes('*')) {
      validationResults.errors.push(
        'Wildcard CORS origins not allowed in production',
      );
      validationResults.valid = false;
    }

    // Check VNC configuration
    const vncUrl = configService.get('BYTEBOT_DESKTOP_VNC_URL');
    if (!vncUrl) {
      validationResults.warnings.push(
        'VNC URL not configured - computer control may not work',
      );
    }

    // Check Redis configuration for rate limiting
    const redisHost = configService.get('REDIS_HOST');
    if (!redisHost && environment !== 'development') {
      validationResults.warnings.push(
        'Redis not configured - rate limiting will use fallback',
      );
    }

    return validationResults;
  }
}

export default {
  BytebotDSecurityConfigService,
  BytebotDSecurityModule,
  BytebotDSecurityDeployment,
};

/**
 * Jest After Environment Setup
 *
 * Custom Jest matchers and test utilities that extend the testing framework.
 * This file runs after the test environment is set up and provides:
 * - Custom Jest matchers for domain-specific assertions
 * - Enhanced error reporting and debugging utilities
 * - Performance monitoring and profiling tools
 * - Test data validation helpers
 *
 * @author Claude Code
 * @version 1.0.0
 */

/* eslint-disable @typescript-eslint/restrict-template-expressions */
/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable @typescript-eslint/no-unsafe-assignment */
/* eslint-disable @typescript-eslint/no-unsafe-member-access */

import { expect } from '@jest/globals';

// Custom Jest matchers for BytebotD testing
expect.extend({
  /**
   * Validates operation ID format (action_timestamp_randomString)
   */
  toBeValidOperationId(received: unknown): jest.CustomMatcherResult {
    const pass =
      typeof received === 'string' &&
      /^[a-z_]+_\d{13}_[a-z0-9]{7}$/.test(received);

    if (pass) {
      return {
        message: () => `Expected ${received} not to be a valid operation ID`,
        pass: true,
      };
    } else {
      return {
        message: () =>
          `Expected ${received} to be a valid operation ID (format: action_timestamp_randomString)`,
        pass: false,
      };
    }
  },

  /**
   * Validates base64 string format
   */
  toBeValidBase64(received: unknown): jest.CustomMatcherResult {
    if (typeof received !== 'string') {
      return {
        message: () => `Expected ${received} to be a string`,
        pass: false,
      };
    }

    try {
      // Test if string can be decoded as base64
      const decoded = Buffer.from(received, 'base64').toString('base64');
      const pass = decoded === received;

      if (pass) {
        return {
          message: () => `Expected ${received} not to be valid base64`,
          pass: true,
        };
      } else {
        return {
          message: () => `Expected ${received} to be valid base64`,
          pass: false,
        };
      }
    } catch (_error) {
      return {
        message: () =>
          `Expected ${received} to be valid base64, but decoding failed: ${_error}`,
        pass: false,
      };
    }
  },

  /**
   * Validates execution time is within reasonable bounds
   */
  toHaveReasonableExecutionTime(
    received: { processingTimeMs?: number; duration?: number } | number,
    maxMs: number,
  ): jest.CustomMatcherResult {
    let executionTime: number;

    if (typeof received === 'number') {
      executionTime = received;
    } else if (received && typeof received === 'object') {
      executionTime = received.processingTimeMs ?? received.duration ?? 0;
    } else {
      return {
        message: () =>
          `Expected ${received} to have processingTimeMs, duration property, or be a number`,
        pass: false,
      };
    }

    const pass = executionTime > 0 && executionTime <= maxMs;

    if (pass) {
      return {
        message: () =>
          `Expected execution time ${executionTime}ms not to be within reasonable bounds (0-${maxMs}ms)`,
        pass: true,
      };
    } else {
      return {
        message: () =>
          `Expected execution time ${executionTime}ms to be within reasonable bounds (0-${maxMs}ms)`,
        pass: false,
      };
    }
  },

  /**
   * Validates screenshot result structure
   */
  toBeValidScreenshotResult(received: unknown): jest.CustomMatcherResult {
    if (!received ?? typeof received !== 'object') {
      return {
        message: () => `Expected ${received} to be an object`,
        pass: false,
      };
    }

    const _result = received as any;
    const hasImage = typeof _result.image === 'string';
    const hasMetadata =
      _result.metadata && typeof _result.metadata === 'object';
    const hasValidTimestamp =
      hasMetadata && _result.metadata.captureTime instanceof Date;
    const hasOperationId =
      hasMetadata && typeof _result.metadata.operationId === 'string';

    const pass = hasImage && hasMetadata && hasValidTimestamp && hasOperationId;

    if (pass) {
      return {
        message: () =>
          `Expected ${received} not to be a valid screenshot result`,
        pass: true,
      };
    } else {
      const issues = [];
      if (!hasImage) issues.push('missing or invalid image');
      if (!hasMetadata) issues.push('missing metadata');
      if (!hasValidTimestamp) issues.push('missing or invalid captureTime');
      if (!hasOperationId) issues.push('missing or invalid operationId');

      return {
        message: () =>
          `Expected ${received} to be a valid screenshot result. Issues: ${issues.join(', ')}`,
        pass: false,
      };
    }
  },

  /**
   * Validates file operation result structure
   */
  toBeValidFileResult(
    received: unknown,
    operation: 'read' | 'write',
  ): jest.CustomMatcherResult {
    if (!received ?? typeof received !== 'object') {
      return {
        message: () => `Expected ${received} to be an object`,
        pass: false,
      };
    }

    const _result = received as any;
    const hasSuccess = typeof _result.success === 'boolean';
    const hasOperationId = typeof _result.operationId === 'string';
    const hasTimestamp = _result.timestamp instanceof Date;
    const hasMessage = typeof _result.message === 'string';

    let operationSpecificChecks = true;
    const issues = [];

    if (operation === 'read') {
      const hasValidReadData = _result.success
        ? typeof _result.data === 'string' && typeof _result.name === 'string'
        : true;
      operationSpecificChecks = hasValidReadData;
      if (!hasValidReadData) issues.push('missing read-specific data');
    } else if (operation === 'write') {
      const hasValidWriteData = _result.success
        ? typeof _result.path === 'string' && typeof _result.size === 'number'
        : true;
      operationSpecificChecks = hasValidWriteData;
      if (!hasValidWriteData) issues.push('missing write-specific data');
    }

    const pass =
      hasSuccess &&
      hasOperationId &&
      hasTimestamp &&

      (_result.success ?? hasMessage) &&
      operationSpecificChecks;

    if (pass) {
      return {
        message: () =>
          `Expected ${received} not to be a valid ${operation} file result`,
        pass: true,
      };
    } else {
      if (!hasSuccess) issues.push('missing or invalid success');
      if (!hasOperationId) issues.push('missing or invalid operationId');
      if (!hasTimestamp) issues.push('missing or invalid timestamp');
      if (!_result.success && !hasMessage) issues.push('missing error message');

      return {
        message: () =>
          `Expected ${received} to be a valid ${operation} file result. Issues: ${issues.join(', ')}`,
        pass: false,
      };
    }
  },

  /**
   * Validates OCR operation result structure
   */
  toBeValidOcrResult(received: unknown): jest.CustomMatcherResult {
    if (!received ?? typeof received !== 'object') {
      return {
        message: () => `Expected ${received} to be an object`,
        pass: false,
      };
    }

    const _result = received as any;
    const hasText = typeof _result.text === 'string';
    const hasConfidence =
      typeof _result.confidence === 'number' &&
      _result.confidence >= 0 &&
      _result.confidence <= 1;
    const hasProcessingTime =
      typeof _result.processingTimeMs === 'number' &&
      _result.processingTimeMs > 0;
    const hasMethod = typeof _result.method === 'string';
    const hasOperationId = typeof _result.operationId === 'string';
    const hasBoundingBoxes =
      !_result.boundingBoxes ?? Array.isArray(_result.boundingBoxes);

    const pass =
      hasText &&
      hasConfidence &&
      hasProcessingTime &&
      hasMethod &&
      hasOperationId &&
      hasBoundingBoxes;

    if (pass) {
      return {
        message: () => `Expected ${received} not to be a valid OCR result`,
        pass: true,
      };
    } else {
      const issues = [];
      if (!hasText) issues.push('missing or invalid text');
      if (!hasConfidence) issues.push('missing or invalid confidence');
      if (!hasProcessingTime)
        issues.push('missing or invalid processingTimeMs');
      if (!hasMethod) issues.push('missing or invalid method');
      if (!hasOperationId) issues.push('missing or invalid operationId');
      if (!hasBoundingBoxes) issues.push('invalid boundingBoxes format');

      return {
        message: () =>
          `Expected ${received} to be a valid OCR result. Issues: ${issues.join(', ')}`,
        pass: false,
      };
    }
  },
});

