 *
 * This module provides enterprise-grade error handling utilities including
 * safe error catching, error transformation, logging, and monitoring integration.
 *
 * @author Error Handling Specialist
 * @version 1.0.0
 * @security-focus Critical
 */

import {
  ApplicationError,
  getErrorMessage as _getErrorMessage,
  getErrorCode as _getErrorCode,
  getErrorContext as _getErrorContext,
  getErrorSeverity,
  isApplicationError,
  isAuthenticationError,
  isAuthorizationError,
  isSecurityError,
  isSystemError,
  isValidationError,
  isHttpError,
} from '../types/error-types';

import {
  ErrorFactory,
  BaseCustomError as _BaseCustomError,
} from '../errors/custom-errors';

/**
 * Result type for operations that may fail
 */
export type Result<T, E = ApplicationError> =
  | {
      success: true;
      data: T;
    }
  | {
      success: false;
      error: E;
    };

/**
 * Async result type for Promise-based operations
 */
export type AsyncResult<T, E = ApplicationError> = Promise<Result<T, E>>;

/**
 * Error context for logging and monitoring
 */
export interface ErrorLogContext {
  operationId: string;
  timestamp: Date;
  userId?: string;
  sessionId?: string;
  clientIp?: string;
  userAgent?: string;
  requestId?: string;
  traceId?: string;
  service: string;
  operation: string;
  duration?: number;
  additionalContext?: Record<string, unknown>;
}

/**
 * Error logging levels
 */
export enum LogLevel {
  DEBUG = 'debug',
  INFO = 'info',
  WARN = 'warn',
  ERROR = 'error',
  FATAL = 'fatal',
}

/**
 * Logger interface for dependency injection
 */
export interface ErrorLogger {
  debug(message: string, context?: Record<string, unknown>): void;
  info(message: string, context?: Record<string, unknown>): void;
  warn(message: string, context?: Record<string, unknown>): void;
  error(message: string, context?: Record<string, unknown>): void;
  fatal(message: string, context?: Record<string, unknown>): void;
}

/**
 * Default console logger implementation
 */
export const defaultLogger: ErrorLogger = {
  debug: (message: string, context?: Record<string, unknown>) =>
    console.debug(`[DEBUG] ${message}`, context ?? ''),
  info: (message: string, context?: Record<string, unknown>) =>
    console.info(`[INFO] ${message}`, context ?? ''),
  warn: (message: string, context?: Record<string, unknown>) =>
    console.warn(`[WARN] ${message}`, context ?? ''),
  error: (message: string, context?: Record<string, unknown>) =>
    console.error(`[ERROR] ${message}`, context ?? ''),
  fatal: (message: string, context?: Record<string, unknown>) =>
    console.error(`[FATAL] ${message}`, context ?? ''),
};

/**
 * Global error handler configuration
 */
export interface ErrorHandlerConfig {
  logger: ErrorLogger;
  enableMonitoring: boolean;
  enableStackTraces: boolean;
  sensitiveFieldPattern: RegExp;
  maxContextSize: number;
}

/**
 * Default error handler configuration
 */
export const defaultErrorHandlerConfig: ErrorHandlerConfig = {
  logger: defaultLogger,
  enableMonitoring: true,
  enableStackTraces: process.env.NODE_ENV !== 'production',
  sensitiveFieldPattern: /(password|token|secret|key|auth|credential)/i,
  maxContextSize: 10000, // Maximum size of context object in characters
};

/**
 * Global error handler instance
 */
let globalErrorHandler: ErrorHandler;

/**
 * Main error handler class
 */
export class ErrorHandler {
  constructor(private config: ErrorHandlerConfig = defaultErrorHandlerConfig) {}

  /**
   * Safe execution wrapper that catches and transforms errors
   */
  async safeExecute<T>(
    operation: () => Promise<T>,
    context: Partial<ErrorLogContext>,
  ): AsyncResult<T> {
    const startTime = Date.now();
    const operationId =
      context.operationId ||
      `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    const fullContext: ErrorLogContext = {
      operationId,
      timestamp: new Date(),
      service: 'unknown',
      operation: 'unknown',
      ...context,
    };

    try {
      this.config.logger.debug(`Starting operation: ${fullContext.operation}`, {
        operationId,
        service: fullContext.service,
      });

      const result = await operation();

      const duration = Date.now() - startTime;
      this.config.logger.debug(
        `Operation completed successfully: ${fullContext.operation}`,
        { operationId, duration, service: fullContext.service },
      );

      return { success: true, data: result };
    } catch (error) {
      const duration = Date.now() - startTime;
      const transformedError = this.transformError(error, {
        ...fullContext,
        duration,
      });

      this.logError(transformedError, { ...fullContext, duration });

      return { success: false, error: transformedError };
    }
  }

  /**
   * Synchronous safe execution wrapper
   */
  safeExecuteSync<T>(
    operation: () => T,
    context: Partial<ErrorLogContext>,
  ): Result<T> {
    const startTime = Date.now();
    const operationId =
      context.operationId ||
      `op_sync_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    const fullContext: ErrorLogContext = {
      operationId,
      timestamp: new Date(),
      service: 'unknown',
      operation: 'unknown',
      ...context,
    };

    try {
      this.config.logger.debug(
        `Starting sync operation: ${fullContext.operation}`,
        { operationId, service: fullContext.service },
      );

      const result = operation();

      const duration = Date.now() - startTime;
      this.config.logger.debug(
        `Sync operation completed successfully: ${fullContext.operation}`,
        { operationId, duration, service: fullContext.service },
      );

      return { success: true, data: result };
    } catch (error) {
      const duration = Date.now() - startTime;
      const transformedError = this.transformError(error, {
        ...fullContext,
        duration,
      });

      this.logError(transformedError, { ...fullContext, duration });

      return { success: false, error: transformedError };
    }
  }

  /**
   * Transform unknown errors into typed ApplicationError instances
   */
  transformError(
    error: unknown,
    context?: Partial<ErrorLogContext>,
  ): ApplicationError {
    // If already an ApplicationError, return as-is
    if (isApplicationError(error)) {
      return error;
    }

    // If it's a standard Error instance, transform it
    if (error instanceof Error) {
      return this.transformStandardError(error, context);
    }

    // Handle primitive types and unknown objects
    return ErrorFactory.system.serviceUnavailable('Unknown service', {
      originalError: error,
      errorType: typeof error,
      context,
    });
  }

  /**
   * Transform standard Error instances into ApplicationError instances
   */
  private transformStandardError(
    error: Error,
    context?: Partial<ErrorLogContext>,
  ): ApplicationError {
    const errorMessage = error.message;
    const errorName = error.name;
    const errorStack = error.stack;

    // Check for common error patterns and transform accordingly
    if (
      errorName === 'UnauthorizedException' ||
      errorMessage.includes('unauthorized')
    ) {
      return ErrorFactory.authentication.unauthorized({
        originalError: error,
        stack: errorStack,
        context,
      });
    }

    if (
      errorName === 'ForbiddenException' ||
      errorMessage.includes('forbidden')
    ) {
      return ErrorFactory.authorization.forbidden(undefined, undefined, {
        originalError: error,
        stack: errorStack,
        context,
      });
    }

    if (
      errorName === 'ValidationError' ||
      errorMessage.includes('validation')
    ) {
      return ErrorFactory.validation.invalidInput(
        undefined,
        undefined,
        undefined,
        {
          originalError: error,
          stack: errorStack,
          context,
        },
      );
    }

    if (errorName === 'TokenExpiredError' ?? errorMessage.includes('expired')) {
      return ErrorFactory.authentication.tokenExpired({
        originalError: error,
        stack: errorStack,
        context,
      });
    }

    if (errorName === 'JsonWebTokenError' ?? errorMessage.includes('jwt')) {
      return ErrorFactory.authentication.tokenInvalid({
        originalError: error,
        stack: errorStack,
        context,
      });
    }

    if (
      errorMessage.includes('rate limit') ||
      errorMessage.includes('too many requests')
    ) {
      return ErrorFactory.security.rateLimitExceeded(undefined, 'medium', {
        originalError: error,
        stack: errorStack,
        context,
      });
    }

    if (
      errorMessage.includes('database') ||
      errorMessage.includes('connection')
    ) {
      return ErrorFactory.system.database(undefined, true, {
        originalError: error,
        stack: errorStack,
        context,
      });
    }

    if (errorMessage.includes('network') ?? errorMessage.includes('timeout')) {
      return ErrorFactory.system.network(undefined, {
        originalError: error,
        stack: errorStack,
        context,
      });
    }

    // Default to system error for unclassified errors
    return ErrorFactory.system.serviceUnavailable(undefined, {
      originalError: error,
      errorName,
      stack: errorStack,
      context,
    });
  }

  /**
   * Log error with appropriate level and context
   */
  logError(error: ApplicationError, context: ErrorLogContext): void {
    const severity = getErrorSeverity(error);
    const logLevel = this.getLogLevelFromSeverity(severity);
    const sanitizedContext = this.sanitizeContext(context);
    const errorDetails = this.buildErrorDetails(error, sanitizedContext);

    switch (logLevel) {
      case LogLevel.DEBUG:
        this.config.logger.debug(error.message, errorDetails);
        break;
      case LogLevel.INFO:
        this.config.logger.info(error.message, errorDetails);
        break;
      case LogLevel.WARN:
        this.config.logger.warn(error.message, errorDetails);
        break;
      case LogLevel.ERROR:
        this.config.logger.error(error.message, errorDetails);
        break;
      case LogLevel.FATAL:
        this.config.logger.fatal(error.message, errorDetails);
        break;
    }

    // Send to monitoring service if enabled
    if (this.config.enableMonitoring) {
      this.sendToMonitoring(error, sanitizedContext);
    }
  }

  /**
   * Build comprehensive error details for logging
   */
  private buildErrorDetails(
    error: ApplicationError,
    context: ErrorLogContext,
  ): Record<string, unknown> {
    const details: Record<string, unknown> = {
      errorName: error.name,
      errorCode: error.code,
      timestamp: error.timestamp,
      operationId: context.operationId,
      service: context.service,
      operation: context.operation,
      duration: context.duration,
    };

    // Add stack trace if enabled
    if (this.config.enableStackTraces && error.stack) {
      details.stack = error.stack;
    }

    // Add error-specific details
    if (isAuthenticationError(error)) {
      details.userId = error.userId;
      details.tokenType = error.tokenType;
    }

    if (isAuthorizationError(error)) {
      details.userId = error.userId;
      details.requiredRole = error.requiredRole;
      details.currentRole = error.currentRole;
      details.requiredPermissions = error.requiredPermissions;
    }

    if (isValidationError(error)) {
      details.field = error.field;
      details.expectedType = error.expectedType;
      details.validationRules = error.validationRules;
    }

    if (isSecurityError(error)) {
      details.clientIp = error.clientIp;
      details.userAgent = error.userAgent;
      details.attackType = error.attackType;
      details.severity = error.severity;
    }

    if (isSystemError(error)) {
      details.service = error.service;
      details.operation = error.operation;
      details.retryable = error.retryable;
    }

    if (isHttpError(error)) {
      details.statusCode = error.statusCode;
      details.statusText = error.statusText;
    }

    // Add context information
    if (context.userId) details.userId = context.userId;
    if (context.sessionId) details.sessionId = context.sessionId;
    if (context.clientIp) details.clientIp = context.clientIp;
    if (context.userAgent) details.userAgent = context.userAgent;
    if (context.requestId) details.requestId = context.requestId;
    if (context.traceId) details.traceId = context.traceId;

    // Add error context
    if (error.context && Object.keys(error.context).length > 0) {
      details.errorContext = error.context;
    }

    // Add additional context
    if (
      context.additionalContext &&
      Object.keys(context.additionalContext).length > 0
    ) {
      details.additionalContext = context.additionalContext;
    }

    return details;
  }

  /**
   * Get log level from error severity
   */
  private getLogLevelFromSeverity(severity: string): LogLevel {
    switch (severity.toLowerCase()) {
      case 'low':
        return LogLevel.INFO;
      case 'medium':
        return LogLevel.WARN;
      case 'high':
        return LogLevel.ERROR;
      case 'critical':
        return LogLevel.FATAL;
      default:
        return LogLevel.ERROR;
    }
  }

  /**
   * Sanitize context to remove sensitive information
   */
  private sanitizeContext(context: ErrorLogContext): ErrorLogContext {
    const sanitized = { ...context };

    // Remove sensitive fields from additional context
    if (sanitized.additionalContext) {
      sanitized.additionalContext = this.sanitizeObject(
        sanitized.additionalContext,
      );
    }

    // Truncate large context objects
    const contextStr = JSON.stringify(sanitized);
    if (contextStr.length > this.config.maxContextSize) {
      sanitized.additionalContext = {
        ...sanitized.additionalContext,
        _truncated: true,
        _originalSize: contextStr.length,
      };
    }

    return sanitized;
  }

  /**
   * Recursively sanitize object to remove sensitive fields
   */
  private sanitizeObject(
    obj: Record<string, unknown>,
  ): Record<string, unknown> {
    const sanitized: Record<string, unknown> = {};

    for (const [key, value] of Object.entries(obj)) {
      if (this.config.sensitiveFieldPattern.test(key)) {
        sanitized[key] = '[REDACTED]';
      } else if (value && typeof value === 'object' && !Array.isArray(value)) {
        sanitized[key] = this.sanitizeObject(value as Record<string, unknown>);
      } else {
        sanitized[key] = value;
      }
    }

    return sanitized;
  }

  /**
   * Send error to monitoring service (placeholder for actual implementation)
   */
  private sendToMonitoring(
    error: ApplicationError,
    context: ErrorLogContext,
  ): void {
    // Placeholder for monitoring service integration
    // In a real implementation, this would send to services like:
    // - Sentry
    // - New Relic
    // - DataDog
    // - Custom metrics endpoint

    this.config.logger.debug('Error sent to monitoring service', {
      errorCode: error.code,
      operationId: context.operationId,
      service: context.service,
    });
  }
}

/**
 * Get or create global error handler instance
 */
export function getErrorHandler(
  config?: Partial<ErrorHandlerConfig>,
): ErrorHandler {
  if (!globalErrorHandler) {
    const fullConfig = { ...defaultErrorHandlerConfig, ...config };
    globalErrorHandler = new ErrorHandler(fullConfig);
  }
  return globalErrorHandler;
}

/**
 * Convenient wrapper functions for common error handling patterns
 */
export const ErrorHandlerUtils = {
  /**
   * Safe async function execution
   */
  async safeAsync<T>(
    operation: () => Promise<T>,
    context: Partial<ErrorLogContext>,
  ): AsyncResult<T> {
    return getErrorHandler().safeExecute(operation, context);
  },

  /**
   * Safe sync function execution
   */
  safeSync<T>(
    operation: () => T,
    context: Partial<ErrorLogContext>,
  ): Result<T> {
    return getErrorHandler().safeExecuteSync(operation, context);
  },

  /**
   * Transform any error to ApplicationError
   */
  transformError(
    error: unknown,
    context?: Partial<ErrorLogContext>,
  ): ApplicationError {
    return getErrorHandler().transformError(error, context);
  },

  /**
   * Log error with proper context
   */
  logError(error: ApplicationError, context: ErrorLogContext): void {
    getErrorHandler().logError(error, context);
  },

  /**
   * Check if operation result was successful
   */
  isSuccess<T>(result: Result<T>): result is { success: true; data: T } {
    return result.success;
  },

  /**
   * Check if operation result was a failure
   */
  isFailure<T>(
    result: Result<T>,
  ): result is { success: false; error: ApplicationError } {
    return !result.success;
  },

  /**
   * Extract data from successful result or throw error
   */
  unwrap<T>(result: Result<T>): T {
    if (result.success) {
      return result.data;
    }
    throw result.error;
  },

  /**
   * Extract data from successful result or return default value
   */
  unwrapOr<T>(result: Result<T>, defaultValue: T): T {
    if (result.success) {
      return result.data;
    }
    return defaultValue;
  },

  /**
   * Chain multiple operations that may fail
   */
  async chain<T, U>(
    result: AsyncResult<T>,
    nextOperation: (data: T) => AsyncResult<U>,
  ): AsyncResult<U> {
    const firstResult = await result;
    if (!firstResult.success) {
      return firstResult;
    }
    return nextOperation(firstResult.data);
  },
};

#!/usr/bin/env node
/**
 * Targeted ESLint Fixes for bytebotd Package
 * Carefully fixes specific common issues without introducing new problems
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

console.log('🎯 Starting targeted ESLint fixes for bytebotd package...\n');

// Get current violation count
function getCurrentViolationCount() {
  try {
    const result = execSync(
      'npx eslint "{src,test}/**/*.ts" 2>&1 | grep -c "error\\|warning"',
      { encoding: 'utf8', cwd: __dirname },
    );
    return parseInt(result.trim());
  } catch (error) {
    return 0;
  }
}

const initialCount = getCurrentViolationCount();
console.log(`📊 Initial violation count: ${initialCount}\n`);

// Target specific problematic files for manual fixes
const targetFiles = [
  'src/cache/cache-key.generator.ts',
  'src/cache/cache.service.ts',
  'src/mcp/compressor.ts',
];

// Fix specific patterns
function fixFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.log(`   ❌ File not found: ${filePath}`);
    return false;
  }

  let content = fs.readFileSync(filePath, 'utf8');
  const originalContent = content;
  let fixesApplied = 0;

  // Fix __error to _error (but be careful about existing _error)
  if (
    content.includes('__error') &&
    !content.includes('_error instanceof Error ? __error')
  ) {
    content = content.replace(/__error/g, '_error');
    fixesApplied++;
    console.log(`   ✅ Fixed __error references`);
  }

  // Fix logger._error to logger.error
  if (content.includes('this.logger._error')) {
    content = content.replace(/this\.logger\._error/g, 'this.logger.error');
    fixesApplied++;
    console.log(`   ✅ Fixed logger._error method calls`);
  }

  // Fix specific undefined 'result' variables in cache files
  if (filePath.includes('cache') && content.includes('result = ')) {
    content = content.replace(/(?<!_)result(\s*=)/g, '_result$1');
    fixesApplied++;
    console.log(`   ✅ Fixed undefined result variables`);
  }

  // Fix _result constant reassignment in compressor.ts
  if (
    filePath.includes('compressor.ts') &&
    content.includes('const _result') &&
    content.includes('_result =')
  ) {
    content = content.replace(/const _result/g, 'let _result');
    fixesApplied++;
    console.log(`   ✅ Fixed const reassignment issue`);
  }

  if (content !== originalContent) {
    fs.writeFileSync(filePath, content, 'utf8');
    console.log(
      `   🎉 ${fixesApplied} fixes applied to ${path.basename(filePath)}`,
    );
    return true;
  } else {
    console.log(`   📝 No changes needed for ${path.basename(filePath)}`);
    return false;
  }
}

// Process target files
let totalFilesFixed = 0;
for (const file of targetFiles) {
  const filePath = path.join(__dirname, file);
  console.log(`🔍 Processing: ${file}`);

  if (fixFile(filePath)) {
    totalFilesFixed++;
  }
  console.log('');
}

// Check improvement
console.log('🧪 Checking violation count after fixes...\n');
const finalCount = getCurrentViolationCount();
const improvement = initialCount - finalCount;

console.log(`📈 Results:`);
console.log(`   Initial violations: ${initialCount}`);
console.log(`   Final violations: ${finalCount}`);
console.log(`   Improvement: ${improvement} violations fixed`);
console.log(`   Files modified: ${totalFilesFixed}`);

if (improvement > 0) {
  console.log(`\n✅ Successfully reduced violations by ${improvement}!`);
} else {
  console.log(`\n⚠️ No improvement detected. May need more targeted fixes.`);
}

console.log('\n🎯 Targeted fixes completed!');

#!/usr/bin/env node

/**
 * Targeted fix for critical undefined variable violations in ByteBotD
 *
 * Focuses on the most severe issues:
 * 1. undefined 'result' variables in test files
 * 2. undefined 'error' and '__error' variable references
 * 3. undefined 'response' variables in tests
 * 4. Missing imports for testing utilities
 *
 * @author Claude Code - Critical ESLint Fixes
 * @version 1.0.0
 */

const fs = require('fs');
const path = require('path');

/**
 * Critical fix patterns
 */
const CRITICAL_FIXES = [
  // Fix undefined result variables in test files
  {
    pattern:
      /(\s+)(result\.(success|status|data|message|path|screenshots|logs|extractedData|executionTimeMs|actionsCompleted|screenshot|timestamp|metadata|size|mediaType))/g,
    replacement: '$1_result.$2',
    description: 'Fix undefined result variables in tests',
  },

  // Fix direct result usage
  {
    pattern: /expect\(result\)/g,
    replacement: 'expect(_result)',
    description: 'Fix undefined result in expect statements',
  },

  // Fix return result statements where result is undefined
  {
    pattern: /return result;/g,
    replacement: (match, offset, string) => {
      const beforeMatch = string.substring(Math.max(0, offset - 200), offset);
      if (
        !beforeMatch.includes('const result') &&
        !beforeMatch.includes('let result') &&
        !beforeMatch.includes('var result') &&
        !beforeMatch.includes('= result')
      ) {
        return 'return _result;';
      }
      return match;
    },
    description: 'Fix undefined result in return statements',
  },

  // Fix __error references
  {
    pattern: /__error/g,
    replacement: '_error',
    description: 'Fix __error variable name mismatches',
  },

  // Fix missing Test imports in test files
  {
    pattern: /^import \{ ([^}]+) \} from '@nestjs\/testing';$/gm,
    replacement: (match, imports) => {
      if (!imports.includes('Test') || !imports.includes('TestingModule')) {
        const newImports = [];
        if (!imports.includes('Test')) newImports.push('Test');
        if (!imports.includes('TestingModule'))
          newImports.push('TestingModule');
        return `import { ${[...newImports, ...imports.split(', ')].join(', ')} } from '@nestjs/testing';`;
      }
      return match;
    },
    description: 'Add missing Test and TestingModule imports',
  },

  // Fix undefined response variables in tests
  {
    pattern: /(\s+)(response\.(status|body|text|headers|data))/g,
    replacement: '$1_response.$2',
    description: 'Fix undefined response variables in tests',
  },

  // Fix loop variable declarations
  {
    pattern: /for\s*\(\s*([a-z]+)\s*=\s*0/g,
    replacement: 'for (let $1 = 0',
    description: 'Fix undeclared loop variables',
  },
];

/**
 * File-specific fixes
 */
const FILE_SPECIFIC_FIXES = {
  'computer-use.service.desktop-automation.spec.ts': {
    patterns: [
      {
        pattern: /const result = await service\.executeAction\([^)]+\);/g,
        replacement: 'const _result = await service.executeAction($1);',
        description: 'Fix result variable declaration in computer-use tests',
      },
    ],
  },

  'computer-use.service.files.spec.ts': {
    patterns: [
      {
        pattern: /'ReadFileAction' is not defined/,
        fix: "Add import: import { ReadFileAction } from '../dto/computer-action.dto';",
      },
    ],
  },
};

/**
 * Apply targeted fixes to critical files
 */
async function fixCriticalUndefinedVariables() {
  console.log('🎯 Applying Targeted Fixes for Critical Undefined Variables\n');

  const srcDir = path.join(__dirname, 'src');
  const criticalFiles = [
    'src/computer-use/__tests__/computer-use.service.desktop-automation.spec.ts',
    'src/computer-use/__tests__/computer-use.service.files.spec.ts',
    'src/common/__tests__/security-validation.e2e-spec.ts',
    'src/common/__tests__/security-validation.mock-spec.ts',
    'src/common/__tests__/security-validation.simple-spec.ts',
    'src/auth/guards/jwt-auth.guard.ts',
    'src/auth/guards/roles.guard.ts',
    'src/cache/cache.service.ts',
    'src/cache/cache-key.generator.ts',
    'src/common/filters/security-exception.filter.ts',
  ];

  let totalFixed = 0;

  for (const filePath of criticalFiles) {
    const fullPath = path.join(__dirname, filePath);

    if (!fs.existsSync(fullPath)) {
      console.log(`⚠️  File not found: ${filePath}`);
      continue;
    }

    console.log(`🔧 Processing: ${filePath}`);

    let content = fs.readFileSync(fullPath, 'utf8');
    let fixes = 0;
    const originalContent = content;

    // Apply general critical fixes
    for (const fix of CRITICAL_FIXES) {
      const beforeFix = content;

      if (typeof fix.replacement === 'function') {
        content = content.replace(fix.pattern, fix.replacement);
      } else {
        content = content.replace(fix.pattern, fix.replacement);
      }

      if (content !== beforeFix) {
        const fixCount = (beforeFix.match(fix.pattern) || []).length;
        fixes += fixCount;
        console.log(`  ✅ ${fix.description}: ${fixCount} fixes`);
      }
    }

    // Apply file-specific fixes
    const fileName = path.basename(filePath);
    if (FILE_SPECIFIC_FIXES[fileName]) {
      for (const specificFix of FILE_SPECIFIC_FIXES[fileName].patterns) {
        const beforeFix = content;

        if (typeof specificFix.replacement === 'function') {
          content = content.replace(
            specificFix.pattern,
            specificFix.replacement,
          );
        } else {
          content = content.replace(
            specificFix.pattern,
            specificFix.replacement,
          );
        }

        if (content !== beforeFix) {
          fixes++;
          console.log(`  🎯 ${specificFix.description}: applied`);
        }
      }
    }

    // Save the file if changes were made
    if (content !== originalContent) {
      fs.writeFileSync(fullPath, content, 'utf8');
      console.log(`  💾 Saved with ${fixes} fixes\n`);
      totalFixed += fixes;
    } else {
      console.log(`  ✅ No changes needed\n`);
    }
  }

  console.log(`🎉 Critical fixes complete! Total fixes applied: ${totalFixed}`);

  return totalFixed;
}

